(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["zh-TW"] = {"ui":{"lead":"人們不只玩遊戲，還把遊戲畫了下來。放大這些跨越3300年的繪畫和雕像，看看其中的細節吧。","details":"看點","links":"查看或遊玩這款遊戲","record":"作品資訊","game":"遊戲","exhibit":"館藏","room":"展廳","room_chance":"擲具","hint":"雙指或滾輪縮放 · 拖曳移動 · 點擊編號","r_artist":"作者","r_date":"年代","r_place":"地區","r_medium":"材質與技法","r_size":"尺寸","r_museum":"收藏","r_credit":"入藏","r_rights":"圖像","met":"大都會藝術博物館","cc0":"開放取用（公有領域）","metlink":"博物館的作品頁面","credit":"圖像來自大都會藝術博物館、克里夫蘭藝術博物館、芝加哥藝術博物館和阿姆斯特丹國家博物館的開放取用（公有領域）。","cma":"克里夫蘭藝術博物館","aic":"芝加哥藝術博物館","rijks":"阿姆斯特丹國家博物館"},"nefertari":{"title":"下塞尼特棋的奈菲爾塔利王后","artist":"妮娜·德·加里斯·戴維斯（摹本）","date":"原畫 約西元前1290—前1224年 · 摹本 1921—22年","place":"埃及（王后谷）","game":"塞尼特","medium":"紙本蛋彩（原尺寸二分之一的摹本）","p":["奈菲爾塔利是拉美西斯二世的正妃。這幅畫是1921—22年在王后谷她的墓中臨摹的壁畫，連原畫的裂縫和缺損都照樣畫了下來。","王后坐在棋盤前，與一位看不見的對手下塞尼特。人們認為，畫在墓中的塞尼特不只是遊戲，還意味著贏得通往來世的旅程。"],"spots":[["兩種棋子","棋盤上排著尖頂的棋子和線軸形的棋子，分屬對局的兩方。"],["王后的手","正要拈起棋子的指尖。"],["棋盤與臺架","棋盤從側面畫出，所以看不到格子。它放在細腳的臺架上。"],["名字的框","橢圓形的框（王名圈）裡寫著王后的名字。"],["看不見的對手","對面沒有人，王后在和看不見的對手對局。"]]},"hydria":{"title":"下棋的阿基里斯與埃阿斯（水罐）","artist":"歸於萊阿格羅斯畫組","date":"約西元前510年","place":"希臘（阿提卡）","game":"骰子遊戲","medium":"陶（黑繪式）","p":["特洛伊戰爭的營地裡，希臘兩位英雄阿基里斯和埃阿斯圍著棋盤消磨時光。這一圖樣是約西元前540年由陶工兼畫家埃克塞基亞斯創造的，原作保存在梵蒂岡博物館的雙耳瓶上。","約西元前540至前480年間，這個題材非常受歡迎，已知有150多例。這只水罐的正中站著女神雅典娜。兩人玩的是擲骰子走棋子的遊戲。"],"spots":[["女神雅典娜","女神雅典娜站在兩人中間。"],["左邊的英雄","手裡仍握著長矛，俯身看著棋盤。"],["右邊的英雄","他也沒有放下武器——戰爭中片刻的遊戲。"],["棋盤","兩人之間的矮臺就是棋盤。"],["肩部的畫","罐肩上畫著出發的戰車。"]]},"liubo":{"title":"下六博的兩人（隨葬俑）","date":"西元前1世紀—西元1世紀","place":"中國（漢）","game":"六博","medium":"彩繪陶","p":["這是兩位下六博的人像。六博在漢代風行一時。這樣的俑放進墓中，寄託著死後也能繼續享樂的願望。","照片中，兩人之間擺著本館館藏的六博棋盤和骨製棋子。人像捕捉了一局激戰中的戲劇性瞬間。"],"spots":[["六博棋盤","與本館館藏「六博棋盤與棋子」是同一塊棋盤，可以看到T、L、V形記號。"],["左邊的棋手","沉著地盯著棋盤。"],["右邊的棋手","一隻手舉起，嘴巴張得大大的，是走出了好棋嗎？"],["盤上的棋子","骨製棋子排在棋盤兩端。"],["盤外的棋子","地上也放著棋子。"]]},"shahnama":{"title":"布祖爾吉米赫爾破解印度的遊戲「象棋」（《塔赫馬斯普國王的列王紀》）","artist":"歸於阿卜杜勒·瓦哈卜","date":"約1530—35年","place":"伊朗（大不里士）","game":"西洋棋","medium":"紙本不透明水彩、墨、銀、金","p":["這是菲爾多西史詩《列王紀》中的一幕。印度國王派使者帶來象棋的棋盤和棋子，向波斯國王努希爾萬挑戰：「如果能解出玩法，印度就納貢。」","只有年輕的賢者布祖爾吉米赫爾在期限內解開了謎題。《列王紀》還說，波斯回贈了雙陸，而印度沒能解開。國王和廷臣們都目不轉睛地盯著棋盤和棋手。"],"spots":[["棋盤","方格棋盤上擺著棋子，小到幾乎看不清形狀。"],["努希爾萬國王","坐在寶座上，等著看謎題如何解開。"],["圍著棋盤的人","俯身看著棋盤的棋手們。"],["詩句","上下的框裡寫著菲爾多西的詩。"],["廷臣們","頭戴豎著紅棒的頭巾的人們，站著觀看。"]]},"chaupar":{"title":"下喬帕爾的濕婆與帕爾瓦蒂（《拉薩曼賈里》組畫之一）","artist":"努爾布爾的德維達薩","date":"1694—95年","place":"印度（巴索利，查謨）","game":"喬帕爾（魯多祖先的近親）","medium":"紙本不透明水彩、墨、銀、金","p":["這是描繪15世紀梵文愛情詩《拉薩曼賈里》的組畫中的一幅。濕婆神和妻子帕爾瓦蒂坐在虎皮上，圍著十字形的棋盤。","濕婆作弊贏走了帕爾瓦蒂的項鍊，她正請求還給她。大膽的色彩、模糊的空間深度，用色彩和手勢表達含義，是巴索利畫派的特點。"],"spots":[["十字形棋盤","喬帕爾和帕奇西的棋盤就是這樣的十字形。"],["盤上的白條","應是喬帕爾所用的長骰子（帕薩）。"],["濕婆","白色的身體，頸上纏著蛇。"],["帕爾瓦蒂","伸出手，請求還她項鍊。"],["虎皮","兩人坐在虎皮上。"]]},"shogi":{"title":"下將棋的青年男女（《中納言兼輔》，三十六歌仙比擬）","artist":"鈴木春信","date":"約1767—69年","place":"日本（江戶）","game":"將棋","medium":"木版畫（錦繪）","p":["這是比擬三十六歌仙的組畫之一，這一幅比擬的是中納言兼輔。夏夜，蚊帳旁，一對青年男女圍著將棋盤。","春信是推廣多色套印「錦繪」的畫師。連棋盤上棋子的排列都畫得很細緻。"],"spots":[["帶腳的將棋盤","和今天一樣帶腳的厚棋盤。"],["小盒子","應是收納棋子的盒子。"],["蚊帳","掛著綠色的蚊帳，是夏夜的場景。"],["行燈","照亮棋盤的燈。"],["和歌牌","雲形的框裡寫著歌仙的名字和和歌。"]]},"sugoroku":{"title":"玩雙六的兩位少女","artist":"初代歌川豐國","date":"江戶時代（18世紀末—19世紀初）","place":"日本（江戶）","game":"盤雙六（雙陸的一種，與西洋雙陸同類）","medium":"木版畫（雙聯）","p":["兩張版畫拼成的大畫面上，聚在客廳裡的少女們正在玩盤雙六。盤雙六與本館館藏的正倉院雙六局一脈相承，是西洋雙陸的同類。","棋盤上排著黑白棋子，右邊的少女手裡拿著筒（搖骰子的容器）。窗外可以看到富士山。"],"spots":[["雙六盤","細長的格子上排著黑白棋子。"],["骰筒","把骰子放進筒裡搖。"],["盤外的棋子","是已經走完的棋子，還是還沒上盤的棋子？"],["富士山","窗外的富士山。"],["兩張的接縫","兩張版畫在這裡相接。"]]},"eakins":{"title":"下西洋棋的人","artist":"湯瑪斯·艾金斯","date":"1876年","place":"美國（費城）","game":"西洋棋","medium":"木板油畫","p":["在費城一戶人家的客廳裡，兩位朋友在下西洋棋，畫家的父親班傑明·艾金斯在一旁觀看。精心構建空間、細緻描繪細節，是畫家在巴黎師從傑洛姆時學到的。","1881年，這幅畫成為大都會藝術博物館接受的第一件在世畫家的捐贈作品。"],"spots":[["棋子","昏暗的房間裡，棋盤上的棋子格外明亮。"],["畫家的父親","站著觀戰的是畫家的父親班傑明。"],["右邊的棋手","畫家喬治·W·霍姆斯，畫家父親的朋友。"],["桌子的抽屜","寫著拉丁文，意思是「班傑明·艾金斯之子繪於76年」。"],["壁爐上方的畫","掛著老師傑洛姆畫作的複製品。"],["貓","地板上，只有貓對棋局毫無興趣。"]]},"weiqi":{"title":"仙人對弈圖盤","artist":"佚名","date":"1425—1436年（明宣德年間）","place":"中國","game":"圍棋","medium":"剔紅剔綠（雕漆）","size":"高3.5、寬14.9、長23.5公分","credit":"佛羅倫斯與赫伯特·歐文夫婦捐贈，2015年","p":["這是一件雕漆盤：先髹塗數十層漆再雕刻，紅漆之下有一層綠漆，靠雕刻深淺顯出不同顏色。花口盤心裡，刻著在松樹下對弈的仙人。","中國有「爛柯」的傳說：樵夫王質在山中觀看仙人下棋，回過神來，斧柄已經爛掉，人間已過了很久。對弈的仙人是很受歡迎的題材。右邊站著的人物是誰，沒有記載。"],"spots":[["棋盤","兩位仙人之間的棋盤，連棋盤線都細細刻出。"],["對弈的仙人","坐在岩石旁圍著棋盤的兩人。"],["站著觀看的人","稍遠處站著的人物，令人想起爛柯傳說中的樵夫，但具體是誰不得而知。"],["月","天上一輪圓月（也可能是太陽）。"],["松","枝幹舒展的松樹，常象徵長壽與仙境。"],["牡丹邊飾","盤緣雕有大朵牡丹與枝葉。"]]},"webb":{"title":"西洋雙陸棋手（陳列櫃）","artist":"菲利普·韋布（設計）、愛德華·伯恩-瓊斯（繪畫）、莫里斯-馬歇爾-福克納公司（製作）","date":"1861年","place":"英國（倫敦）","game":"西洋雙陸棋","medium":"彩繪松木、皮革上油彩、黃銅、銅","size":"高185.4、寬114.3、深53.3公分","credit":"羅傑斯基金，1926年","p":["這是威廉·莫里斯與友人於1861年創辦的公司最早期的家具之一。櫃門的皮革上用油彩畫著身穿中世紀服裝的一男一女正在下雙陸。它還在1862年的倫敦國際博覽會上展出。","它很好地體現了美術工藝運動想要消除「美術」與「工藝」界限的理念。皮革背景上打出細密的小點，是仿照中世紀的技法。"],"spots":[["棋盤","兩人之間桌上的西洋雙陸棋盤。"],["男子","手拿棋子、凝視棋盤的年輕男子。"],["女子","坐在對面的女子，手裡拿著棋子（或骰盅）。"],["腳邊的花","兩人的腳邊開著花。"],["打點的皮革","背景皮革上打出細密的小點，在光下閃爍。"],["菱形紋帶","櫃門上下圍著金底菱形紋樣的飾帶。"]]},"liberale":{"title":"下棋的人們","artist":"利貝拉萊·達·維羅納","date":"約1475年","place":"義大利（維羅納）","game":"西洋棋","medium":"木板蛋彩","size":"34.9×41.3公分","credit":"梅特蘭·F·格里格斯遺贈，1943年","p":["這是文藝復興時期義大利「卡索內」（裝新娘嫁妝的彩繪箱）正面板畫的殘片。畫家利貝拉萊也以為錫耶納大教堂的唱詩本繪製插圖而聞名。","畫的是一個不知名愛情故事裡的場景。另一塊殘片上，窗邊的少女似乎在招呼青年進來；這幅畫裡，兩人正在下西洋棋。據美術館的解說，少女快要輸了。西洋棋是當時愛情文學裡常用來比喻情場較量的題材。"],"spots":[["棋盤","紅白相間的棋盤上擺著深色棋子，棋局似乎已近尾聲。"],["青年","伸手向棋盤的青年，看來這局他要贏了。"],["少女","坐在對面的少女；在另一塊殘片上，她從窗口招呼青年。"],["窗外","敞開的窗外是山丘和天空。"],["觀棋的青年們","抱著雙臂看棋的男子們。"],["觀棋的少女們","從柱子後面探看棋局的少女們。"]]},"mirror":{"title":"下西洋棋的戀人鏡盒","artist":"佚名","date":"1325—1350年","place":"法國（巴黎）","game":"西洋棋","medium":"象牙","size":"直徑10.2公分","credit":"J·H·韋德基金購藏，1940年","p":["這塊手掌大小的象牙圓片，原本是手鏡的蓋子。14世紀的巴黎人把磨亮的金屬鏡夾在兩片象牙板之間隨身攜帶；這樣的象牙雕刻是宮廷和貴族喜愛的奢侈品。","掛著帷幕的帳篷裡，一位青年和一位女士正在下西洋棋。在中世紀的故事裡，西洋棋同時象徵愛情與戰爭。有人認為兩人是崔斯坦與伊索德，或蘭斯洛與桂妮薇兒，但並無定論。美術館向觀眾發問：你覺得誰會贏？"],"spots":[["棋盤","放在獨腳桌上的棋盤，上面立著幾枚棋子。"],["青年","他伸手去走下一步棋。"],["女士","戴頭巾的女士，指尖碰著盤上的棋子。"],["握著的手","另一隻手握著放在膝上。是握著吃掉的棋子嗎？"],["帳篷的帷幕","兩側繫起的帷幕——這是刻有下棋場景的鏡盒常見的舞台。"]]},"morris":{"title":"莫里斯棋（九子棋）棋盤","artist":"彼得·弗勒特納","date":"1500—1546年","place":"德國","game":"九子莫里斯棋","medium":"木刻版畫","credit":"查爾斯·W·哈克尼斯基金，1923年","p":["這是活躍於文藝復興時期紐倫堡的雕塑家彼得·弗勒特納的木刻版畫。他還以裝飾圖樣、家具、金匠的模型和一副諷刺意味十足的撲克牌設計而聞名。捲曲的蔓草紋下藏著的，是德語稱為「磨坊」（Mühle）的九子莫里斯棋盤：三個套在一起的正方形，在各邊中點相連。","棋盤上有24個點。把自己的三枚棋子連成一線（成「磨」），就能吃掉對方一枚。這樣的版畫也是工匠的範本，美術館曾把這張作品放進金匠模型與圖樣的展覽。人們是直接在紙上下棋，還是把它刻到木頭或金屬上，沒有留下記錄。"],"spots":[["中心的正方形","最裡面的正方形，填滿細密的蔓草紋。"],["外圈的角","外側正方形的角——放棋子的24個點之一。"],["中圈的角","中間正方形的角也是放棋子的點。"],["相連的線","在各邊中點連接三個正方形的帶子，棋子也沿著它走。"],["面具","上下左右是捲曲的飾框和人臉，典型的文藝復興怪誕紋樣。"],["葡萄藤邊框","葉子和果實在黑底上刻成白色。"]]},"leifeng":{"title":"雷峰塔棋盤","artist":"佚名","date":"1736—1795年（乾隆年間）","place":"中國","game":"競走棋（擲骰前進）","medium":"木版畫，紙本墨印","size":"31×29.8公分","credit":"J·H·韋德基金購藏，2025年","p":["這是清代乾隆年間印製、用來玩的單張印刷品。格子裡畫的是民間故事《白蛇傳》的人物：白蛇精白娘子（白娘）、她的同伴小青、青年許宣（後來的版本作許仙），以及最後把白娘子鎮壓在西湖邊雷峰塔下的法海和尚。","路線從寫著「起馬」的格子盤旋著通向中心的塔。玩家大概像西方的鵝棋那樣，擲骰子沿著故事比賽前進，但玩法沒有留下記錄。據美術館介紹，這類彩色單張版畫在城市裡出售，掛在牆上，成為城市視覺文化的一部分；每種顏色都用單獨刻的版來印。"],"spots":[["起馬","寫著「起馬」的格子，應該是起點。"],["白娘與小青","白蛇精白娘子和她的同伴小青。"],["許宣","與白娘子結為夫妻的青年。"],["法海禪師","把白娘子鎮在塔下的和尚。"],["雷峰塔","杭州西湖邊的雷峰塔，故事結束的地方。"],["中心","塔前坐著的女子和跪著的男子——故事最後一幕，也許就是終點。"]]},"tutinama":{"title":"受傷的猴子咬了棋友王子的手（《鸚鵡故事》插圖）","artist":"達薩萬塔","date":"約1560年","place":"印度（阿克巴的蒙兀兒宮廷）","game":"西洋棋","medium":"紙本水粉、墨、金","size":"20×14.2公分（畫面10.2×10.6公分）","credit":"A·迪恩·佩里夫人捐贈，1962年","p":["這是蒙兀兒帝國阿克巴宮廷製作的故事集《鸚鵡故事》（Tuti-nama）的插圖。母鸚鵡給孩子們講故事，告誡牠們不要和狐狸崽這樣不同種類的動物交朋友，這是其中一則：一隻擅長西洋棋的猴子，常常和王子下棋。","有一天王子宴客，猴子在席上開了個失禮的玩笑，被王子打了一巴掌，猴子便咬了王子的手。右邊屋外僕人在準備飯菜，客人們看得目瞪口呆。下方的題記寫著達薩萬塔的名字，他後來成為蒙兀兒宮廷最著名的畫家之一；年輕的他在畫面下先塗了一層清涼的藍色。"],"spots":[["猴子","咬住王子的手——牠是王子的棋友。"],["王子","被咬了手的王子。"],["棋盤","放在地上的紅格棋盤。"],["吃驚的客人","應邀赴宴的客人們。"],["準備飯菜","外面把鍋架在火上的僕人們。"],["波斯文","上方框裡用波斯文寫著故事。"]]},"teniers":{"title":"雙陸對局","artist":"大衛·特尼爾斯","date":"1640年代","place":"法蘭德斯","game":"西洋雙陸","medium":"木板油畫，後轉移到畫布","size":"59×80.6公分","credit":"塞繆爾·D·懷斯夫婦捐贈，1943年","p":["法蘭德斯畫家特尼爾斯畫的一場押了重注的西洋雙陸大戰。這種遊戲歷史悠久，現代形式出現於15世紀，而「backgammon」這個名字大約就誕生在這幅畫的年代。17世紀它非常流行，常常用來賭錢。","兩位對手周圍擠滿看客，牆邊還有人在記分。從窗口探頭的女人等細節看，美術館認為這裡是妓院裡的賭博間。這類遊戲場景常帶著訓誡：賭博愚蠢、甚至邪惡，而且浪費時間。"],"spots":[["棋盤","桌上打開的雙陸棋盤，對局正在進行。"],["白襯衫的男人","背對我們的棋手，正伸手去拿棋子。"],["托腮的男人","對面的棋手，托著腮陷入沉思。"],["記分的人","在牆上的板子上做記號的男人——記的是分數還是賭注？"],["窗口的女人","從窗口往下看的年長女人。"],["裡屋","裡屋的男人們在一位年輕女子身旁喝酒。"]]},"imari":{"title":"下圍棋的兩人方盤","artist":"佚名","date":"18世紀","place":"日本（江戶時代）","game":"圍棋","medium":"瓷器，模製，釉上彩（肥前窯，伊萬里風格）","size":"2.4×13.8公分","credit":"塞弗倫斯與葛麗塔·米利金收藏，1964年","p":["這只小小的方盤上，兩人在松樹下下圍棋：穿黃衣的人對著直接放在地上的棋盤坐著，穿綠衣的對手靠在樹上。","這是肥前（今佐賀、長崎）燒製的伊萬里瓷器，綠色的用法讓人想起九谷彩繪。它是為外銷而做的——當時日本已取代中國，成為歐洲瓷器的主要供應者。"],"spots":[["棋盤","畫著格子的圍棋盤，直接放在地上。"],["黃衣人","面向棋盤坐著的人。"],["綠衣人","靠在樹上微笑的對手。"],["松樹","在頭頂伸展枝條的松樹。"],["紅框","切去四角的紅框圍住畫面。"]]},"shoei":{"title":"琴棋書畫圖屏風（一扇）","artist":"傳狩野松榮","date":"16世紀末—17世紀初","place":"日本（桃山時代）","game":"圍棋","medium":"六曲一雙之一，紙本墨畫淡彩","size":"153×358.6公分","credit":"約翰·L·塞弗倫斯基金，1979年","p":["這是傳為狩野派畫家狩野松榮所作的六曲屏風。它和另一扇成對，描繪中國文人應具備的修養「琴棋書畫」——彈琴、下棋、書法和繪畫。松樹下的原野上，身分高貴的中國士人帶著僕從在休憩。","畫面中央兩人在下圍棋，另一人在旁觀看。旁邊的桌上放著書和仍裝在布套裡的琴，等著人來彈。這是一幅娛樂與禮儀兼顧的場景。據美術館介紹，有個僕人被水裡游動的魚吸引了注意。"],"spots":[["棋盤","帶腳的棋盤，兩位士人相對而弈。"],["士人們","對弈的兩人，和在旁觀看的一人。"],["桌上","應是放著書和套中之琴的桌子。"],["僕從","在桌邊侍候的僕從。"],["看魚的僕人","趴在水邊，看著魚游動的僕人。"],["松樹","在畫面上方伸展枝條的大松樹。"]]},"umaya":{"title":"馬廄圖屏風（廊下的圍棋與將棋）","artist":"作者不詳","date":"16世紀前期","place":"日本（室町時代）","game":"圍棋、將棋","medium":"六曲一雙屏風之一；紙本設色、金","size":"146.1×346.6公分","credit":"愛德華·L·惠特莫爾基金購藏，1934年","p":["這是由6扇連成的屏風，左右兩件為一組，這是其中之一。主題或許是馬廄裡拴著的名馬，但前面的廊下也熱鬧非凡。","廊下的人們在下兩種棋：左邊是圍棋，右邊是將棋。依美術館的解說，躁動的馬匹與靜心謀劃的棋局相映成趣，使畫面充滿生氣。在日本，猴子被視為馬的守護者，馬廄裡有時也養猴。"],"spots":[["圍棋盤","畫著細密格線、擺著黑子的棋盤。"],["戴烏帽子的兩人","頭戴黑色烏帽子的男人們：穿綠衣的伸手向棋盤，穿紅衣的在旁觀看。"],["將棋盤","格子很大的棋盤，與圍棋盤相比，格數少得多。"],["大笑的對手","光頭的僧人拈起棋子，對面的男人抱著頭大笑。是誰剛占了上風嗎？"],["猴子","廊下的一端，好像是一隻穿紅衣的猴子。"],["馬","揚起前蹄的黑馬，被繩子拴著。"]]},"goryeo":{"title":"下棋人物紋鑲嵌青瓷注子","artist":"作者不詳","date":"13世紀","place":"朝鮮半島（高麗）","game":"圍棋（韓語「巴督」）","medium":"青瓷，白土與黑土鑲嵌","size":"高20.4公分，徑14.3公分","credit":"約翰·L·塞弗倫斯捐贈，1917年","p":["這是一件高麗青瓷注子（有流和把手的酒器）。在胎上刻線、填入白土和黑土，再施釉燒成的「鑲嵌」是高麗陶工的拿手技法。圓形的框裡，柳樹下坐著的兩人以白色浮現出來。","兩人之間有一個棋盤，美術館認為這一場面可與下圍棋（韓語稱「巴督」）的圖像相比。琴、棋、書、畫「四藝」被視為文人應有的修養，他們風雅的聚會也成了工藝品上的圖案。描繪人物的高麗鑲嵌青瓷十分罕見。"],"spots":[["棋盤","兩人之間的棋盤，用白土表現為方形。"],["左邊的人","面向棋盤坐著的人。"],["右邊的人","坐在對面的對手。"],["柳","垂在兩人頭上的柳枝，用黑土描繪。"],["雲紋框","圓框四周環繞著捲雲般的紋樣。"],["開片","釉面細密的裂紋。燒成後冷卻時，因胎與釉收縮程度不同而產生。"]]},"kangra":{"title":"露台上玩喬帕爾的二人","artist":"作者不詳","date":"約1790—1800年","place":"印度（帕哈里，康格拉畫派）","game":"喬帕爾","medium":"素描，赭紅起稿","size":"19.4×13.2公分","credit":"愛德華·L·惠特莫爾基金購藏，1936年","p":["這是喜馬拉雅山麓帕哈里地區康格拉畫家的素描。先用紅線（赭紅顏料）起稿，再用黑線修整。因為沒有上色，人物和器物的線條一目了然。","一男一女坐在露台上，隔著十字形的棋盤玩喬帕爾。喬帕爾與帕奇西使用同樣的十字盤，是印度自古流行的競走遊戲，擲長骰（帕薩）來走棋。棋盤上還沒有畫出格子。侍女們在兩人身旁侍候。"],"spots":[["十字棋盤","放在地上的十字形棋盤，格子還沒畫。"],["女子","掌心朝上的女子，是要擲骰子嗎？"],["男子","纏著帶羽飾頭巾的男子，把手伸向棋盤。"],["左邊的侍女","她拿著小瓶，伸出一塊布。"],["右邊的侍女","她拿著長柄的器具和一個小容器。"],["紅色底稿","頭巾周圍，黑線下面露出紅色的底稿。"]]},"vuillard":{"title":"跳棋對局（選自《風景與室內》）","artist":"愛德華·維亞爾","date":"1899年","place":"法國","game":"西洋跳棋","medium":"彩色石版畫（第3版次）；奧古斯特·克洛印製，安布魯瓦茲·沃拉爾出版","size":"畫面33×25.7公分（紙張38×30.8公分）","credit":"漢納基金捐贈，1951年","p":["畫商安布魯瓦茲·沃拉爾也是重要的版畫出版人。1895年他請波納爾創作了12幅彩色石版畫的畫集，此後又接連出版多部畫集，維亞爾的《風景與室內》便是其中之一，由名印刷師奧古斯特·克洛印製。","波納爾和維亞爾同屬「那比派」（希伯來語意為「先知」），他們追求以形與色本身來表達情感的新藝術，喜歡描繪都市生活與家庭日常。在滿是花紋的房間裡，兩個男人隔著跳棋盤對弈，一位女子站著觀戰。法語把跳棋叫作「dames」，左下角的鉛筆字可讀作「partie de dames」，即「一局跳棋」。"],"spots":[["棋盤","小小的方格棋盤，上面擺著棋子。"],["左邊的男人","留鬍子的男人把手伸向棋盤。"],["右邊的男人","對手坐在扶手椅上低頭看棋，被站著的女子擋住了一半。"],["站著的女子","她手托下巴，關注著勝負。"],["燈","牆邊的燈。壁紙和椅子的布面都布滿花紋。"],["鉛筆字","左下角用鉛筆寫著「partie de dames」（一局跳棋）。"]]},"talbot":{"title":"下西洋棋的人（早期照片）","artist":"傳為威廉·亨利·福克斯·塔爾博特","date":"約1843—47年","place":"英國","game":"西洋棋","medium":"鹽紙印相","size":"19.9×15公分","credit":"埃弗里特·科夫勒夫婦出資購藏","p":["塔爾博特發明的「負片—正片法」能用一張底片印出任意多張照片，直到數位時代都是攝影的基礎。他早期的實驗既體現了對科學的興趣，也體現了藝術上的抱負。研究證實，他拍過10張以上下棋人的照片。","不過這一張可能並非他本人所攝：同一場景的照片都沒有簽名，紙張也與他慣用的不同。照片中的人大概是攝影師安托萬·克洛代和塔爾博特的助手尼古拉斯·亨尼曼。新的研究認為，這些照片在克洛代的工作室拍攝，後歸亨尼曼所有，再由他作為抵債的一部分交給塔爾博特（美術館解說）。"],"spots":[["棋盤","桌上的棋盤，棋子排成一列列。"],["戴高禮帽的男人","戴著帽子，伸手去拿棋子。"],["沉思的男人","手托下巴，盯著棋盤的對手。"],["幕布","後面垂下的幕布，大概是拍照用的背景。"],["另一頂帽子","右邊的台子上還放著一頂高禮帽。"]]},"pvl":{"title":"擲骰子的男人們","artist":"PVL大師","date":"約1520年","place":"尼德蘭","game":"骰子","medium":"紙本銅版畫（雕刻凹版）","size":"9.4×9.4公分（圓形）","credit":"查爾斯·哈克與赫恩家族信託收藏，2023年購藏","p":["這是16世紀初活躍於尼德蘭、姓名不詳的銅版畫家的作品。左下角刻著「PVL」的組合字母，因此人稱「PVL大師」。在只有手掌大小的圓形畫面上，用密密麻麻的細線刻畫出房間的縱深和衣服的質感。","桌上有兩顆骰子。探身的男人和毛皮領子的青年伸著手指爭論著什麼，也許是在爭點數。後面的女人們探頭觀看，桌下放著酒壺。骰子自古與賭博相連，屢次遭到禁止。"],"spots":[["骰子","桌上滾動的兩顆骰子。"],["指著的手","兩人的手指在桌上碰到一起。是在爭點數嗎？"],["寬簷帽的男人","探身向前的男人。開衩的蓬袖是當時流行的服飾。"],["毛皮領子的青年","戴大帽子、穿毛皮領子的青年。"],["觀看的女人們","從後面探頭看賭局的女人們。"],["組合字母","左下的「PVL」，是這位畫家名字的唯一線索。"]]},"kiyohiro":{"title":"玩雙六的人","artist":"鳥居清廣","date":"約1750年","place":"日本（江戶時代）","game":"盤雙六","medium":"紅摺繪（套色木版，大判），版元鱗形屋","size":"43.5×29.3公分","credit":"克拉倫斯·白金漢收藏","p":["鳥居清廣是約1737年至1776年活躍的浮世繪畫師。這幅是「紅摺繪」，用紅（胭脂）和綠等少數幾塊色版套印，屬於1765年多色「錦繪」誕生之前的配色。","在黑色台座的棋盤上玩的是盤雙六：兩人擲骰子，移動白子和黑子，先把自己的棋子全部走出的一方獲勝。它與西方的雙陸（西洋雙陸棋）同屬一類，浮世繪中常常畫女性玩盤雙六的情景。後面的女子一邊吸著菸管，一邊觀戰。"],"spots":[["棋盤","帶台座的雙六盤，擺著白子和黑子。"],["左邊的人","伸手移動棋子。"],["右邊的女子","俯身看著棋子的對手。"],["拿菸管的女子","在後面吸著長菸管，觀看勝負。"],["舉起的手","右邊的女子舉著一個黑色的小東西，是搖骰子的筒嗎？"],["署名","「鳥居清廣筆」的署名和版元鱗形屋的印。"]]},"ingram":{"title":"中國象棋","artist":"約翰·英格拉姆（據布歇原畫）","date":"1741—63年","place":"法國（巴黎）","game":"象棋","medium":"蝕刻與雕刻凹版","size":"紙張39.4×27.7公分（版面24.5×16.4公分）","credit":"伊萊沙·惠特爾西收藏，1966年","p":["這是倫敦出生的版畫家約翰·英格拉姆根據法國畫家弗朗索瓦·布歇的素描刻製的銅版畫。英格拉姆移居巴黎，在1741年至1763年間把布歇的「中國風」（歐洲人想像中的中國）作品一幅幅刻成版畫。下方題字為「LE JEU D'ECHETS CHINOIS」（中國象棋）。","高髻的女子在膝上的棋盤上走棋，一個小孩在旁觀看。畫中的遊戲被認為是中國象棋，但真正的象棋棋子都是扁平的圓片，這裡卻有高高的棋子和小小的方塊。椰子樹和坐在罐上的人像，與其說是真實的中國，不如說是當時歐洲夢想中的遠方國度。"],"spots":[["棋盤與棋子","膝上的棋盤，擺著高棋子和方棋子。真正的象棋棋子是扁平圓片。"],["拈子的手","女子的右手在走棋。"],["托腮","左手托著下巴，低頭看棋盤。"],["觀看的孩子","站在棋盤旁觀看對局的孩子。"],["罐上的人像","盤腿坐在大罐頂上的人像。"],["題字與署名","「布歇畫」「英格拉姆刻」的署名和題字「LE JEU D'ECHETS CHINOIS」。"]]},"posada":{"title":"鵝棋","artist":"何塞·瓜達盧佩·波薩達","date":"1909年","place":"墨西哥","game":"鵝棋","medium":"鋅版凸版，紙本","size":"29.3×39.4公分","credit":"威廉·麥卡林·麥基紀念基金","p":["這是以骷髏畫「卡拉韋拉」聞名的墨西哥版畫家波薩達，為墨西哥城出版商安東尼奧·巴內加斯·阿羅約製作的、用來玩的單張印刷品。左下的飄帶上寫著「JUEGO DE LA OCA」（鵝棋），棋路從第1格起盤旋到中心的63。","中央印著玩法（EXPLICACION）：第一次擲出5和4就到26，擲出6和3就到53。停在鵝（鳥）格就按同樣點數再走一次；19的客棧（Venta）休息兩輪；31的井（Poso）和52的監獄（Carcel）要等別人來才能出去；42的迷宮退回39；58的死亡（Muerte）回到起點；必須正好走到63才算贏。停在某些格還要付賭注，這也是一種賭博遊戲。"],"spots":[["玩法","中央的「EXPLICACION」，寫著各格的規則和付賭注的方法。"],["第1格","起點。從這裡盤旋著走向中心。"],["井（31）","像噴泉一樣的井。掉進去就要等別人來才能出去。"],["死亡（58）","骷髏格。停在這裡就回到起點。"],["題字飄帶","左下飄帶上寫著「JUEGO DE LA OCA」，下面孩子們在玩耍。"],["出版商的名字","女神手中的飄帶寫著「IMPRENTA DE A. VANEGAS ARROYO」，出版過許多波薩達版畫的出版商。"]]},"jintile":{"title":"女子對弈畫像磚","artist":"作者不詳","date":"13世紀","place":"中國（金）","game":"棋戲（應為圍棋）","medium":"陶（模製浮雕）","size":"高27.3公分，寬24.8公分，厚5.4公分","credit":"亞洲藝術之友捐款購藏，2002年","p":["這是統治中國北方的女真王朝——金（1115—1234年）時期燒製的浮雕磚。開花的樹下，兩位女子在台上相對而坐，中間放著一個棋盤。","棋盤上刻著細密的格子，應是在下圍棋。右邊的女子探身指著棋盤，左邊的女子看著。金代北方的墓葬中，常見以表現日常生活的浮雕磚裝飾墓壁，這塊磚大概也出自這樣的墓葬。"],"spots":[["棋盤","格子細密的棋盤，應為圍棋盤。"],["指點的手","右邊的女子指著棋盤，是在考慮下一手嗎？"],["左邊的女子","高髻，注視著棋盤。"],["右邊的女子","探身向著棋盤。"],["花樹","兩人頭上伸展著開花的樹枝。"],["台座","兩人所坐的台，腿間有波形裝飾。"]]},"kyosai":{"title":"一個屁掀翻了棋局（畫冊選頁）","artist":"河鍋曉齋","date":"19世紀中後期","place":"日本（江戶—明治時代）","game":"圍棋","medium":"折頁畫冊（26個對開頁）之一；紙本墨筆淡彩","size":"畫冊（合起）28×18公分","credit":"安妮與安東尼·多費捐贈（紀念埃文·特納）","p":["這是活躍於幕末至明治的畫家河鍋曉齋（1831—1889年）畫冊中的一頁，用迅疾奔放的墨線畫在折頁畫冊上。曉齋受過狩野派嚴格的訓練，同時以妖怪畫、戲畫和諷刺畫廣受歡迎。","美術館的標題就說明了一切：「一個屁掀翻了棋局」。左邊戴烏帽子的男人彎下腰，右邊的棋盤飛上半空，棋罐裡的棋子如雨灑落，對手仰面跌倒。認真的對局被一下子毀掉——曉齋用他飛快的筆，畫出了日本自古畫卷中就有的「屁」的笑料。"],"spots":[["戴烏帽子的男人","彎腰撅臀的男人，大概就是禍首。"],["飛起的棋盤","畫著格子的棋盤斜著飛了出去。"],["棋罐與棋子","兩個棋罐翻倒，棋子傾瀉而下。"],["扇子","棋盤旁一把打開的扇子也被吹飛了。"],["仰倒的對手","仰面倒地、瞪大眼睛的男人。"],["筆線","彷彿不打草稿一氣呵成的有力墨線。"]]},"yokuts":{"title":"賭戲盤","artist":"約庫特人織工（姓名不詳）","date":"約1900年","place":"美國（加利福尼亞州鄧拉普附近）","game":"胡丘伊什（核桃殼骰子）","medium":"植物纖維（盤繞編織）","size":"高5.1公分，直徑61公分","credit":"倫納德·S·弗洛斯海姆夫人出資購藏","p":["加利福尼亞的許多原住民都玩碰運氣的遊戲。這個盤用於「胡丘伊什」，一種只有女性玩的骰子遊戲：把八顆核桃殼骰子擲在盤上，用小棍計分。","盤上編織的圓形圖案表現的正是這個遊戲本身——骰子、計分棍和遊戲的人（美術館解說）。這是一件把自己遊戲的畫面織在身上的遊戲用具。照片中，核桃殼骰子放在盤上和盤的四周。"],"spots":[["遊戲的人","沿著盤邊排列的人形，是參加遊戲的人。"],["計分棍","一束束短豎線，表示計分用的小棍。"],["圓形圖案","小小的圓形圖案，也許表示骰子？"],["核桃骰子","核桃殼做的骰子。把八顆擲在盤上。"],["三角帶","深色三角相連的帶子，繞盤一周。"],["中心","編織從中心盤旋而出，外面圍著一圈虛線般的環。"]]},"hokkei":{"title":"牛若丸以雙六勝弁慶","artist":"魚屋北溪","date":"約1825年","place":"日本（江戶時代）","game":"盤雙六","medium":"摺物（色紙判套色木版）","size":"21.8×19.1公分","credit":"海倫·C·岡索勒斯捐贈","p":["這是葛飾北齋的弟子魚屋北溪（1780—1850年）的摺物。摺物是狂歌同好等為印上自己的詩歌而特別訂製的版畫，比市售浮世繪用紙更好，還用金屬顏料，做工講究。","牛若丸是英雄源義經少年時的名字，弁慶是力大無窮的僧兵。兩人最有名的相遇是京都五條大橋上的決鬥，而這幅摺物把較量換成了盤雙六：少年從容地坐在棋盤對面，背著長刀的弁慶撓頭認輸。這大概是一種「見立」的戲仿。"],"spots":[["雙六盤","箱形的雙六盤，擺著白子和黑子。"],["撓頭的弁慶","身披鎧甲的弁慶輸了，正在撓頭。"],["牛若丸","坐在棋盤對面的少年牛若丸。"],["長刀","弁慶背著的大薙刀的刀刃。"],["狂歌","右上的詩句，大概是訂製摺物的同好所作。"],["署名","右下框內北溪的署名。"]]},"vorsterman":{"title":"玩雙陸的人（夜景）","artist":"盧卡斯·埃米爾·福斯特曼（據亞當·德·科斯特原畫）","date":"約1630年","place":"法蘭德斯（安特衛普）","game":"雙陸（西洋雙陸棋）","medium":"雕刻凹版，象牙色紙","size":"畫面25.5×34.4公分","credit":"伯納德·F·羅傑斯收藏","p":["亞當·德·科斯特是1630年前後安特衛普擅長燭光夜景的畫家。同一時期，福斯特曼在同一座城市把當紅畫家的作品刻成版畫。他是魯本斯的學生，與老師失和、去英國之後，開始製作明暗強烈、更具風格化的卡拉瓦喬式版畫，這幅就是一例。","昏暗的房間裡，男人們圍著桌上的雙陸棋盤。仿照德·科斯特對光的處理，兩支燭火照亮了桌邊的面孔（美術館解說）。右邊抱著魯特琴的少年望向我們。"],"spots":[["棋盤","桌上像盒子一樣打開的雙陸棋盤。"],["蠟燭","燭台上的蠟燭，火光照亮人們的臉。"],["抽菸斗的男人","戴寬簷帽的男人叼著菸斗看棋。"],["背對的男人","雙手撐桌、探身向前的男人。"],["彈魯特琴的少年","抱著魯特琴、朝我們微笑的少年。"],["署名","左下「A. De Coster pi.」，右下「Vorsterman」。"]]},"zorn":{"title":"下西洋棋的人","artist":"安德斯·佐恩","date":"1891年","place":"瑞典","game":"西洋棋","medium":"蝕刻版畫，象牙色直紋紙","size":"畫面13.5×9.6公分（版13.9×10公分）","credit":"華萊士·L·德沃爾夫與查爾斯·迪林的佐恩蝕刻收藏","p":["這是瑞典藝術家安德斯·佐恩（1860—1920年）的蝕刻版畫。佐恩以油畫和水彩肖像聞名國際，同時也留下了大量銅版畫。這塊版只有手掌大小。","只靠層層疊加的快速斜線，昏暗的房間和人物就從銅版上浮現出來。前面的男人背對我們，俯身看棋盤；對面的人低著頭思考下一步。棋盤上用細線畫著棋子。畫的是誰，沒有留下記錄。"],"spots":[["棋盤與棋子","下方明亮的部分是棋盤，短豎線是棋子。"],["前面的男人","背對我們、俯身看棋盤的男人。"],["對面的人","低頭注視棋盤的對手。"],["暗色背景","用豎線疊出的昏暗房間深處。"],["斜線","外衣用迅速的斜線層層疊出。"],["署名","版下用鉛筆簽著「Zorn」。"]]},"harunobu-sugoroku":{"title":"觀棋（盤雙六）","artist":"鈴木春信","date":"約1766年","place":"日本（江戶時代）","game":"盤雙六","medium":"套色木版（中判，摺物）","size":"28.5×21公分","credit":"克拉倫斯·白金漢收藏","p":["鈴木春信（1725?—1770年）是1765年前後用多塊色版套印的「錦繪」誕生時的核心畫師。這幅是特別印製的摺物，柔和的色彩層次體現了當時的新意。","梅花盛開的廳堂裡，兩位少女隔著箱形的雙六盤對局，另一位站著俯看棋盤。盤上排著白子和黑子，左邊的少女在走子，右邊的也伸手向盤。後面的隔扇上畫著瀑布和松樹。"],"spots":[["雙六盤","箱形的盤雙六棋盤，擺著白子和黑子。"],["左邊的少女","穿千紙鶴圖案的和服，正在走子。"],["右邊的少女","俯身伸手向棋盤的對手。"],["觀棋的少女","站著俯看棋局，手持長柄器具。"],["梅","從上方伸出枝條的白梅。"],["隔扇畫","畫著瀑布和松樹的隔扇。"]]},"kota":{"title":"科塔王吉肖爾·辛格二世禮拜克里希納","artist":"作者不詳","date":"約1825年","place":"印度（拉賈斯坦，科塔）","game":"帕奇西","medium":"紙本膠彩、銀、金","size":"24.5×18.8公分","credit":"詹姆斯·阿爾伯特與瑪麗·加德納·福特紀念基金","p":["拉賈斯坦小土邦科塔的君主（1819—1828年在位）身著普什提·馬爾格派祭司的服裝，獻上燃著五朵火焰的燈。祭壇小龕裡供奉著克里希納與兩位妃子的金屬像，這尊神像只在科塔受到禮拜。","天花板上垂下許多玻璃燈，通往祭壇的台階上擺著給克里希納和同伴們解悶的玩具和遊戲用具：黃銅大象、銀牛、球，還有一塊帕奇西棋盤（美術館解說）。那塊紅色十字形的布就是棋盤——帕奇西作為神的玩物被供奉在這裡。"],"spots":[["帕奇西棋盤","台階上紅色十字形的布，就是帕奇西棋盤。"],["大象","兩頭黃銅大象立在棋盤旁。"],["球","上一級台階上的金色小球。"],["克里希納像","小龕裡供奉的克里希納與兩位妃子像。"],["君主與燈","身著祭司服的君主獻上五焰燈。"],["玻璃燈","天花板上垂下的許多玻璃燈。"]]},"coyote":{"title":"郊狼棋","artist":"何塞·瓜達盧佩·波薩達的追隨者","date":"年代不詳","place":"墨西哥","game":"郊狼與母雞（狐狸與鵝一類）","medium":"鋅版凸版，紙本","size":"38.2×30.5公分","credit":"威廉·麥卡林·麥基紀念基金","p":["這是和波薩達為墨西哥城民間印坊所作的作品一樣、用鋅版凸版印製的單張遊戲紙。上方大字寫著「JUEGO DEL COYOTE」（郊狼棋），四周畫著偷襲雞舍的郊狼和揮棍驅趕的人。下方的橫條寫著「伊爾德豐索·T·奧雷利亞納所有」。","下方的「EXPLICACION」印著玩法：兩人對弈，一方有15隻母雞，另一方只有一隻郊狼。母雞只能向前或向旁走，不能後退；郊狼可向任何方向走，若母雞身後是空位，就跳過去把牠吃掉。母雞把郊狼圍得動彈不得就贏了。這和歐洲的「狐狸與鵝」是同一類追捕遊戲。"],"spots":[["郊狼的位置","中央圓圈裡的郊狼頭，郊狼從這裡出發。"],["母雞的位置","畫著母雞的圓圈，母雞棋子擺在這裡。"],["玩法","「EXPLICACION」，寫著棋子數、走法和勝負。"],["標題","「JUEGO DEL COYOTE」——郊狼棋。"],["撲向母雞的郊狼","左下，一隻郊狼撲向母雞。"],["揮棍的人","右上，一個人舉棍驅趕郊狼。"]]},"mons":{"title":"以蒙斯（貝亨）為注的雙陸，1709年","artist":"彼得·諾爾佩（製版與出版）","date":"版1623—53年，印於約1709年","place":"荷蘭（阿姆斯特丹）","game":"特里克特拉克（雙陸的一種）","medium":"蝕刻、雕刻凹版與活字詩","size":"紙張35.8×18.6公分（版12.9×17.5公分）","credit":"","p":["四個男人在桌邊玩特里克特拉克。據美術館記錄，字母A至D分別是馬爾伯勒公爵、巴伐利亞選帝侯、奧韋克爾克勳爵和維勒魯瓦公爵。這是一幅諷刺版畫，把1709年聯軍從法國手中圍攻並奪取蒙斯（荷蘭語稱貝亨）一事，比作一場以城市為賭注的棋局。後面的房間（E）裡，西班牙國王腓力五世和一位女子在一起。","版上署「諾爾佩製、出版」，但畫家彼得·諾爾佩在17世紀50年代初已去世，因此這大概是在17世紀的舊版上加刻字母、配上新詩重新印刷的。下方的詩開頭說，大人物的遊戲無非是tiktak和verkeer（兩種雙陸類遊戲），接著逐一挖苦各位玩家。"],"spots":[["棋盤","桌上的特里克特拉克盤——以城市為注的一局。"],["A 馬爾伯勒公爵","站著俯看棋盤的人，聯軍的英國將領。"],["B 巴伐利亞選帝侯","摘了帽子、深陷在椅子裡的人。"],["C 奧韋克爾克勳爵","戴羽飾帽子的人，荷蘭軍隊的將領。"],["E 後面的房間","門那邊的臥室裡，腓力五世和一位女子。"],["詩","下方用活字印的荷蘭語詩，按A至E逐一諷刺。"]]},"stembus":{"title":"投票箱——政治鵝棋","artist":"約翰·米夏埃爾·施密特·克蘭斯（版畫）","date":"1867年","place":"荷蘭","game":"鵝棋（諷刺）","medium":"石版畫","size":"66×50公分","credit":"","p":["這是一幅做成鵝棋樣式的諷刺版畫，附在1867年3月2日出版的週刊《荷蘭觀察家》第9期裡，另附一張寫有玩法的單頁（美術館記錄）。格子裡是當時各位大臣的肖像。","起點是海牙的議會所在地比嫩霍夫，終點在棋盤中央第64格「因蘇林德」（荷屬東印度的雅稱）：爪哇島上吊著大臣彼得·邁耶爾的肖像畫。邁耶爾由殖民大臣轉任東印度總督，這一任命在政壇掀起軒然大波。比通常的63格多出一格，大概就是為了這個笑點。"],"spots":[["起點","左上的建築，遊戲從海牙的比嫩霍夫（議會）開始。"],["邁耶爾的肖像","第63格：裝在畫框裡的彼得·邁耶爾肖像，用繩子吊在島上。"],["因蘇林德 64","中央的島和「64」字樣，這裡是終點。"],["投票箱","右下的「DE STEMBUS」（投票箱），標題裡的箱子。"],["大臣們","格子的窗口裡排著當時大臣們的面孔。"],["公雞","格子裡的一隻公雞，諷刺的是什麼尚不清楚。"]]},"koorai":{"title":"圍著棋盤的朝鮮人（選自西博德《日本》）","artist":"詹姆斯·埃克斯萊本（石版），據「Toioske」原畫","date":"1832—52年","place":"荷蘭（萊頓）／朝鮮人","game":"棋戲（應為圍棋）","medium":"色調石版畫，手工上色","size":"紙張38×55.5公分","credit":"F·G·瓦勒捐贈","p":["這是德國出生的醫生西博德根據在長崎荷蘭商館期間（1823—1830年）的見聞、在萊頓出版的巨著《日本》（NIPPON）中的一幅。右上寫「TAB. I」，下方寫「KOORAI」（高麗），並用荷蘭語和德語註明「漁夫一家」。石版由埃克斯萊本繪製，版上註明原畫作者為「Toioske」。","四個男人坐在地上圍著棋盤，左邊一位女子牽著小孩，右邊站著一個拿長棍和袋子的男人。前面地上放著一頂寬簷黑帽（笠子）。棋盤上畫著格子和圓形棋子，應是在下圍棋（韓語「巴督」），但記錄裡只寫「棋戲」。"],"spots":[["棋盤","格子上放著圓形棋子，應是在下圍棋。"],["黑帽","放在地上的寬簷黑帽（笠子）。"],["母與子","牽著孩子觀看對局的女子。"],["站著的男人","拿著長棍和袋子站著的男人。"],["俯身的男人","穿藍上衣的男人俯身看棋盤。"],["標題","「KOORAI」（高麗），以及荷蘭語和德語的「漁夫一家」。"]]},"cairo":{"title":"咖啡館前圍著棋盤的人們（開羅）","artist":"德利耶與貝夏爾（伊波利特·德利耶、埃米爾·貝夏爾）","date":"約1869—90年","place":"埃及（開羅）","game":"棋戲（應為西洋棋）","medium":"蛋白照片","size":"10.8×16.4公分","credit":"","p":["這是在開羅開設照相館的法國攝影師伊波利特·德利耶和埃米爾·貝夏爾拍攝的照片。襯板上印著照相館的名字「埃茲貝基亞花園旁」和「開羅（埃及）」。這類照片是到訪埃及的旅客買來做紀念的。","男人們坐在裝著格子窗的店門前的地上，圍著矮架上的棋盤。棋盤上立著好幾枚高高的棋子，應是西洋棋（阿拉伯語「沙特蘭吉」），但美術館記錄只寫著「棋戲」。為了拍照，大家都一動不動。"],"spots":[["棋盤與棋子","矮架上的棋盤，立著高棋子，應是西洋棋。"],["格子窗","裝著木格子的窗戶，開羅老房子常見的樣式。"],["拄杖的男人","拿著手杖坐著看棋的男人。"],["籃子","放在地上的編織籃。"],["觀看的孩子","從後面探看棋盤的孩子。"],["照相館名","襯板上的「AU JARDIN DE L'ESBÉKIEH」和「CAIRE (EGYPTE)」。"]]},"vanmour":{"title":"打牌的亞美尼亞人聚會","artist":"讓-巴蒂斯特·范穆爾","date":"約1720—37年","place":"鄂圖曼帝國（伊斯坦堡）","game":"紙牌","medium":"布面油畫","size":"44.5×58.5公分","credit":"","p":["生於法蘭德斯的畫家范穆爾，1699年隨法國大使來到伊斯坦堡，此後一直住在這座城市直到去世，描繪宮廷典禮和市民生活。美術館記錄說，從衣著可以看出畫中的男人是亞美尼亞人。","在一支大蠟燭的光下，男男女女圍著鋪紅布的桌子打牌。桌上擺著發好的牌，也有人盯著手裡的牌。左邊角落裡，一位老婦人在紡線。記錄沒有寫是哪種牌戲。"],"spots":[["桌上的牌","鋪紅布的桌上放著的紙牌。"],["大蠟燭","照亮眾人的一支蠟燭。"],["紡線的老婦","左邊角落紡線的老婦人。"],["看牌的女子","右端盯著手牌的女子。"],["穿毛皮的男人","穿毛皮鑲邊外衣的男人，衣著表明是亞美尼亞人。"],["探身的人","探身向桌、手裡拿牌的人。"]]},"algiers":{"title":"下棋的三個男人（阿爾及爾）","artist":"佚名","date":"1851—1900年","place":"阿爾及利亞（阿爾及爾）","game":"棋戲（應為雙陸）","medium":"蛋白照片","size":"14.0×10.0公分","credit":"","p":["這是一張作者不詳的照片，照片下方手寫著「Alger（阿爾及爾）」。在素色背景前擺著椅子和小桌，應是在照相館拍的。這類拍攝北非人物的照片，是旅客和收藏家買來的。","兩個男人隔著一塊有邊框的棋盤相對而坐，右邊的人正伸手去拿棋子。棋盤上疊著圓形棋子，應是雙陸（當地稱「塔烏拉」等），但記錄只寫著「棋戲」。前面的小桌上放著咖啡用具。"],"spots":[["棋盤與棋子","有邊框的棋盤上疊放著圓棋子。"],["站著看的男人","腰纏寬帶、站在後面俯看棋局的男人。"],["左邊的老人","頭裹布巾、陷入沉思的老人。"],["右邊的男人","頭披白布、俯身看棋盤的男人。"],["咖啡用具","鏤雕小桌上的托盤和小杯。"],["移動棋子的手","右邊棋手正要拿棋子的手。"]]},"circo":{"title":"馬戲遊戲（Juego del Circo）","artist":"曼努埃爾·馬尼利亞（推定）","date":"年代不詳","place":"墨西哥","game":"用兩枚骰子的賭博遊戲","medium":"凸版（木口木刻或照相凸版）·黃褐色紙","size":"26.2×35.0公分","credit":"","p":["這是一張遊戲用的單頁印刷品，美術館認為是墨西哥版畫家曼努埃爾·馬尼利亞所作（帶問號）。右下角印著出售它的版畫店「埃爾·特阿特羅」的名字和地址。這類便宜的印刷品在街頭出售，看來人們不剪開就直接拿來玩。","中間是馬戲帳篷，四周排著馬上雜技、疊羅漢、大力士等圖，每格都標著2到12的數字。左上的「說明」寫道：多少人、小孩也能玩；擲兩枚骰子，把賭注放在點數對應的格子上，若格子裡已有賭注就拿走。擲出12的人贏走全部。"],"spots":[["馬戲帳篷","「JUEGO DEL CIRCO」標題和作為12號格的帳篷。"],["玩法說明","以「ESPLICACION（說明）」開頭的玩法文字。"],["馬上雜技","在奔馬背上跳舞的藝人，6號格。"],["疊羅漢","一人站在另一人肩上，4號格。"],["大力士","舉起像大砲一樣重物的男人，8號格。"],["版畫店名","「De venta, Estampería ‘El Teatro’」和地址。"]]},"loteria":{"title":"墨西哥羅特里亞圖卡","artist":"何塞·瓜達盧佩·波薩達","date":"1880—1913年","place":"墨西哥","game":"羅特里亞（喊圖配對遊戲）","medium":"凸版（木口木刻或照相凸版）·黃褐色紙","size":"30.0×40.0公分","credit":"","p":["墨西哥版畫家波薩達為墨西哥城出版商安東尼奧·瓦內加斯·阿羅約畫了大量插圖，這家出版商印行新聞、歌曲和遊戲的廉價單頁。這張上也印著「JUEGO DE LOTERIA（羅特里亞遊戲）」的標題和瓦內加斯·阿羅約的名字。","紙上排著38幅標有名字的小圖：星星、月亮、蠍子、魔鬼、骷髏、公雞、印刷所等。羅特里亞是類似賓果的遊戲：喊牌人抽牌喊出圖名，玩家若在自己的板上有這張圖，就用豆子等做記號。這張紙應是剪開當牌用的。"],"spots":[["標題與出版商","「JUEGO DE LOTERIA」和瓦內加斯·阿羅約店名。"],["星星","「ESTRELLA」，左上第一幅。"],["月亮","「LUNA」，有臉的彎月。"],["死神","「MUERTE」，拿著大鐮刀吹笛的骷髏。"],["採龍舌蘭汁的人","「TLACHIQUERO」，收集龍舌蘭汁的男人。"],["印刷所","「IMPRENTA」，操作印刷機的工匠，正是印這類單頁的地方。"]]},"jeupol":{"title":"「波蘭棋」即國際跳棋棋盤","artist":"佚名","date":"1833—1900年","place":"比利時或荷蘭","game":"國際跳棋（10×10格）","medium":"木刻，活字印刷文字","size":"32.2×39.6公分","credit":"","p":["這張單頁上方印著法語和荷蘭語的標題「JEU POLONAIS OF DAMSPEL」。「波蘭棋」是法國對10×10格跳棋的稱呼。右上角印著出版商的編號「n. 106」。","正如美術館記錄所說，盤上黑白各50格、共100格，左右有裝飾邊。沒有印棋子，所以應是用豆子或鈕扣當棋子、直接在紙上下的廉價棋盤。紙上還留著摺痕。"],"spots":[["標題","「JEU POLONAIS OF DAMSPEL」字樣。"],["編號","出版商編號「n. 106」。"],["左邊飾","直排圓形花紋的邊飾。"],["右邊飾","與左邊相同的花紋。"],["100個格子","10×10的棋盤，黑格用細線刻成。"],["摺痕","紙上留下的摺痕，或許曾摺起來隨身攜帶。"]]},"dkaart":{"title":"可剪下的骨牌與紙牌","artist":"佚名（布雷波爾斯版）","date":"1800—1833年","place":"比利時（蒂倫豪特）","game":"骨牌與紙牌","medium":"木刻（藍、紅、黃著色），活字印刷文字","size":"34.3×41.9公分","credit":"","p":["據美術館記錄，這張紙印著可剪下使用的32張紙牌和28枚骨牌，是出版商布雷波爾斯目錄中的第114號，下方印著零售商「D. 普韋爾斯（貝亨奧普佐姆）」。標題用荷蘭語和法語並列。","左邊從0-0到6-6的28枚骨牌排成三角形。右邊是各花色7到10加人頭牌和A，共32張，是玩皮克牌等用的一副牌。因為沒有被剪開，我們能看到它剛印好時的樣子。"],"spots":[["標題","「DOMINO EN KAARTSPEL」字樣。"],["雙白","三角形頂端沒有點的0-0骨牌。"],["雙六","最下排右端、最大的6-6。"],["黑桃A","左列從上數第二張。"],["人頭牌","用紅、藍、黃上色的國王牌。"],["零售商名","下方的「D. POUWELS, Bergen-op-Zoom」。"]]},"apen":{"title":"玩雙陸的兩隻猴子","artist":"奎林·布爾（據達維德·特尼爾斯原畫）","date":"1635—1690年","place":"法蘭德斯","game":"特里克特拉克（雙陸的一種）","medium":"蝕刻版畫","size":"11.0×14.5公分","credit":"","p":["這是讓猴子模仿人類行為的「猴戲圖」系列（扉頁加六幅）中的一幅。左下寫著「D. 特尼爾斯原作並出版，特許」，由奎林·布爾把法蘭德斯畫家特尼爾斯的構圖刻成版畫。","正如美術館記錄所說，兩隻猴子坐在地上，中間是一副特里克特拉克棋盤。左邊的猴子用玻璃杯喝酒，右邊的猴子戴著插公雞羽毛的帽子，伸手去拿棋子。這應是在嘲笑沉迷酒和賭博的人。"],"spots":[["棋盤","放在地上的折疊式棋盤，能看到三角形格和棋子。"],["左邊的猴子","穿著外衣坐在棋盤前的猴子。"],["酒杯","左邊猴子舉著的玻璃杯。"],["羽毛帽","右邊猴子帽子上插的公雞羽毛。"],["酒壺","左邊猴子腳邊的壺。"],["題銘","「D Teniers in et excud cum privilegio」字樣。"]]},"dstereo":{"title":"在桌邊玩骨牌的男人們（立體照片）","artist":"佚名","date":"1850—1880年","place":"不詳（荷蘭語題字）","game":"骨牌","medium":"蛋白照片（立體照片）","size":"8.5×17.0公分","credit":"","p":["這是左右並排兩張幾乎相同照片的立體照片。用專門的觀看鏡（立體鏡）看，就會合成一個有縱深的立體畫面。左邊手寫著「Het dominospel（骨牌遊戲）」。","人們在建築前的陽光下擺了張桌子，穿襯衫的男人們手裡拿著骨牌。兩人站著看牌局，右邊的人戴著白帽子。因為大家必須保持不動，這個場面應是為拍照佈置的。"],"spots":[["桌上的骨牌","手裡扣著的骨牌。"],["戴白帽的男人","坐在右邊拿著骨牌的男人。"],["繫圍巾的男人","脖子上繫著圍巾、站著俯看的男人。"],["左邊的男人","支著胳膊看牌的年輕人。"],["題字","左邊手寫的「Het dominospel.」。"],["另一張","右邊的照片，從稍微錯開的位置拍攝，兩張合起來看就是立體的。"]]},"gojo":{"title":"下棋的兩位女子","artist":"佚名","date":"1870—1891年","place":"日本","game":"應為圍棋","medium":"手工上色蛋白照片","size":"9.0×13.5公分","credit":"","p":["這是在黑白照片上用毛筆上色的手工上色照片。這類照片由橫濱等地的照相館製作，作為賣給外國人的紀念品。這張原貼在一本馬尼拉旅行的相簿裡。","以壁龕式的陳設和屏風為背景，兩位女子隔著有腳的棋盤對坐，左邊的女子正在落子。棋盤上有黑白棋子，應是圍棋，但美術館記錄寫的是「棋戲」。前面的托盤裡擺著點心和器皿。"],"spots":[["棋盤與棋子","帶腳的厚棋盤上有黑白棋子。"],["落子的手","左邊女子正在落子。"],["左邊的女子","回頭看向我們的女子，腰帶打著大結。"],["右邊的女子","穿條紋和服的女子，手放在棋盤邊。"],["托盤與器皿","前面擺著的點心和茶杯。"],["插花","身後架子上的花瓶。"]]},"meade":{"title":"下西洋棋的兩個男人","artist":"查爾斯·理查德·米德、亨利·威廉·馬修·米德","date":"1852年","place":"美國","game":"西洋棋","medium":"達蓋爾銀版照片","size":"6.9×8.3公分","credit":"","p":["這是生於英國、移居美國的米德兄弟照相館拍攝的達蓋爾銀版照片。達蓋爾銀版是在鍍銀銅板上直接成像的照片，無法加印，每張都是孤品，因此裝在帶金色框的小皮盒裡。","兩個年輕人隔著小架子上的棋盤對坐，左邊的人手指搭在棋子上。右邊的人手按胸口，盯著棋盤。因為必須長時間不動，這步棋應是擺出來的姿勢。"],"spots":[["棋盤","鋪花布的架子上的棋盤和白棋子。"],["左邊的男人","手指搭在棋子上的人。"],["右邊的男人","低頭看棋盤的人。"],["按在胸口的手","右邊那人若有所思的手。"],["桌布","鋪著花布的小架子。"],["金色框","保護影像的金色框和盒子。"]]},"weiqidai":{"title":"仙人弈棋山水圖","artist":"傳戴進","date":"明代，15—16世紀","place":"中國","game":"圍棋","medium":"立軸，絹本設色","size":"175.2×106.7公分","credit":"","p":["這是一幅傳為明代畫家戴進（約1388—1462年）所作的大立軸。戴進是浙江人，以筆力雄健的山水著稱，後被奉為「浙派」之祖。高聳的山崖和大樹下，人物畫得很小。","樹蔭下的地上，兩位仙人隔著畫有縱橫線的棋盤對坐，旁邊放著果盤和器皿。左邊蹲著的人物，讓人想起在山中看仙人下棋、斧柄都爛掉了的樵夫故事（「爛柯」），但美術館的題目只說是「仙人弈棋」。"],"spots":[["棋盤","有邊框的棋盤，畫著細密的格子。"],["長鬚仙人","長鬚的仙人，悠然坐著看棋盤。"],["青巾仙人","俯身向棋盤的仙人，膝邊有棋子罐。"],["蹲著的人","在左邊探看棋局的人，或許就是爛柯故事裡的樵夫。"],["果盤與器皿","棋盤那邊的盤子和壺。"],["款印","右上的署款和兩方朱印。"]]},"reise":{"title":"環遊世界之旅（水路與陸路）","artist":"佚名","date":"19世紀","place":"應為德語地區","game":"擲骰賽跑遊戲（下注玩）","medium":"石版畫","size":"42.5×33.7公分","credit":"","p":["這是一張遊戲用單頁，用德語題為「環遊世界之旅，水路與陸路——新穎有趣的骰子遊戲」。圓形棋盤上排著1到41格，畫著熱氣球、帆船、輪船、火車和各國人物等。右下角編號「No. 107」。","下方用德、英、荷、法四種語言印著玩法：每人先付15馬克到公共的「旅費錢袋」，然後輪流擲一枚骰子移動記號。停在大圖格上贏2馬克，停在沒有圖的格子罰2馬克，正好到達41的人拿走剩下的全部。"],"spots":[["41：驛馬車","中央的終點，載客的驛馬車和車夫。"],["1：英國人","起點格，戴高禮帽的「Engländer」。"],["熱氣球","飄在空中的熱氣球格。"],["帆船","張滿帆的船。"],["火車","冒著煙的蒸汽機車。"],["玩法","用四種語言印的規則。"]]},"huchten":{"title":"以命相賭的骰子","artist":"揚·范·胡赫滕堡","date":"1680—1720年","place":"荷蘭","game":"骰子","medium":"布面油畫","size":"67.5×76.0公分","credit":"","p":["這是以戰爭畫聞名的荷蘭畫家胡赫滕堡（1647—1733年）的作品，左下有簽名。美術館的標題是「以命相賭的骰子遊戲」。要塞外，兩名囚犯在鼓面上擲骰子，軍官和士兵圍在四周。","右後方立著絞刑架，左邊的要塞牆上也有士兵在看。這應是被判罪的士兵用骰子決定誰受刑的場面。一名囚犯指著鼓，另一名跪著看點數。"],"spots":[["鼓與骰子","代替桌子的鼓，骰子就擲在上面。"],["指著鼓的囚犯","站著指向鼓面的囚犯。"],["跪著的囚犯","穿白襯衫、俯身在鼓上的囚犯。"],["馬上的軍官","戴帽子、從馬上俯視的軍官。"],["絞刑架","右上方的絞刑架。"],["牆上的士兵","在要塞牆上觀看的士兵們。"]]},"vertu":{"title":"美德遊戲（Spel der Deugd）","artist":"揚·赫里茨·菲瑟（J. 福爾曼設計）","date":"1798年","place":"荷蘭","game":"兩枚骰子的賭博遊戲","medium":"雕版、蝕刻、活字印刷","size":"56.9×38.0公分","credit":"","p":["這是一張用荷蘭語和法語題為「美德遊戲」的大幅遊戲版畫。在列柱神殿中央坐著「美德」，左邊站著「繁榮」，右邊是「貧窮」；柱子上掛著誠實、感恩、愛等美德的圓章，下面的台座畫著貪婪、驕傲、懶惰等惡行。","據下方規則，可用兩枚骰子玩，也可抽籤玩。用骰子時，大家共下注63，按太陽運行的方向輪流擲。每種點數對應一種美德或惡行：雙六「美德」拿走全部賭注，雙一「惡行」要付8。圖下的「T」是拿的數，「B」是付的數。"],"spots":[["標題","山牆上的「SPEL DER DEUGD」。"],["美德","中央寶座上的「美德（LA VERTU）」，雙六拿走全部。"],["繁榮","拿著豐饒角的「繁榮」。"],["惡行","雙一的「惡行（LE VICE）」，舉杯的孩子。"],["貪婪","台座上的「貪婪（L’AVARICE）」，下面的「B」和骰點是要付的數。"],["玩法","下方密密印著的規則。"]]},"charros":{"title":"走私的牛仔（骰子遊戲）","artist":"何塞·瓜達盧佩·波薩達","date":"年代不詳","place":"墨西哥","game":"擲骰賽跑遊戲（三枚骰子）","medium":"石版畫","size":"29.9×40.4公分","credit":"","p":["這是一張波薩達繪圖的賽跑遊戲，題為「LOS CHARROS CONTRABANDISTAS（走私的查羅）／JUEGO DE DADOS（骰子遊戲）」。下方印著出版商「A. 瓦內加斯·阿羅約印刷所，墨西哥」，右下有波薩達的簽名。查羅是墨西哥的騎馬牧人，四角畫著戴寬邊帽策馬奔馳的他們。","用繩紋框起的圓格在盤面上蜿蜒，裡面畫著動物、人物、火車等。右上的「說明」說要用三枚骰子：第一次就擲出三個一點即獲勝，落在骷髏格就輸；鹿格可從彩池中拿取，強盜格要付錢，獅子格要停住直到有人來。"],"spots":[["標題","「LOS CHARROS CONTRABANDISTAS／JUEGO DE DADOS」。"],["說明","以「EXPLICACION」開頭的玩法。"],["玩遊戲的人","左下圍著桌子玩棋盤的人們。"],["骰子","盤面中間畫的三枚骰子。"],["馬上的查羅","揮舞套索、策馬奔馳的查羅。"],["出版商名","「IMPRENTA DE A. VANEGAS ARROYO, MÉXICO」。"]]},"snuffwq":{"title":"繪對弈人物鼻煙壺","artist":"中國","date":"清代道光年間（1820—50年），道光款","place":"中國","game":"圍棋","medium":"瓷胎粉彩","size":"高5.7公分","credit":"","p":["這是清代用來裝鼻煙隨身攜帶的小瓶。美術館記錄說有道光款，年代為1820—50年。在約六公分高的白瓷瓶身上，用釉上彩畫著山景和人物。","洞穴般的山石旁，兩位老人隔著放在藍色台子上的棋盤對坐，左邊的老人正要落子。他身後有個拄杖的孩子在看。題材應是讓人想起看仙人下棋的樵夫故事。"],"spots":[["棋盤","藍色台子上畫著細格的棋盤。"],["長鬚老人","穿紫衣、伸手向棋盤的老人。"],["對面的老人","坐在右邊、舉手看棋的老人。"],["拄杖的孩子","在後面拄杖觀看的孩子。"],["山洞","身後洞穴般的山石。"],["瓶塞","綠色的瓶塞。"]]},"ostade":{"title":"酒館裡玩特里克特拉克的人們","artist":"阿德里安·范·奧斯塔德","date":"1653年","place":"荷蘭（哈勒姆）","game":"特里克特拉克（雙陸的一種）","medium":"蝕刻版畫","size":"8.5×7.4公分","credit":"","p":["這是以描繪農民生活著稱的哈勒姆畫家奧斯塔德的一幅巴掌大小的蝕刻版畫，下方刻著「A. ostade」的簽名。昏暗的酒館裡，鉛框窗戶透進的光照著人們。","左邊桌旁兩人隔著特里克特拉克棋盤對坐，後面一人探頭看著。右邊一個男人靠牆坐著，手裡拿著杯子。地上還倒著大酒壺，像是酒館裡悠閒的午後。"],"spots":[["棋盤","桌上的特里克特拉克棋盤。"],["左邊的棋手","戴帽子、面對棋盤的男人。"],["右邊的棋手","俯身在棋盤上的男人。"],["探頭看的人","站在後面看棋的男人。"],["休息的人","靠牆坐著、手拿杯子的男人。"],["鉛框窗","菱形格子的窗，光從這裡進來。"]]},"lenain":{"title":"擲骰子的人們","artist":"馬蒂厄·勒南的追隨者","date":"1630—1680年","place":"法國","game":"骰子","medium":"布面油畫","size":"92.8×119.7公分","credit":"","p":["這是一位效仿法國勒南兄弟中最小的馬蒂厄畫風的畫家所作。據美術館說，加布里埃爾·德·聖奧班畫過同樣構圖的速寫，藏於巴黎國家圖書館。","戶外的小圓桌旁，三個男人在擲骰子；兩人在旁觀看，左邊的人抱著酒瓶。右邊站著兩隻細長的獵犬，開口外是廣闊的原野。桌上的白色小東西就是骰子。"],"spots":[["桌上的骰子","滾在圓桌上的骰子。"],["戴淺色帽的男人","坐著伸手查看點數的男人。"],["黑衣男子","手叉腰站著的年輕人。"],["後面的少年","在桌後看著的少年。"],["抱瓶的男人","左邊抱著瓶子、朝我們笑的男人。"],["兩隻獵犬","右前方細長的狗。"]]},"tunisie":{"title":"阿拉伯咖啡館前的紙牌遊戲（安特衛普世博會突尼西亞館）","artist":"佚名（Ch. 伯恩赫夫特印製）","date":"1894年","place":"比利時（安特衛普）","game":"紙牌","medium":"珂羅版","size":"15.4×21.6公分","credit":"","p":["這是收錄1894年安特衛普世界博覽會照片49幅的一套圖版之一，上方印著「EXPOSITION UNIVERSELLE D’ANVERS 1894」，下方印著「突尼西亞——阿拉伯咖啡館前的紙牌遊戲」。印製者是盧森堡宮廷攝影師伯恩赫夫特。","照片攝於為世博會突尼西亞區修建的、有圓頂和塔樓的廣場。穿突尼西亞服裝的男人們圍著鑲瓷磚的小桌打牌，有人在抽水煙，旁邊還有放茶杯的托盤。右邊坐著穿西裝的觀眾，這應是展示遠方生活的展覽。"],"spots":[["牌桌","圍著鑲瓷磚小桌拿著牌的男人們。"],["水煙","左邊男人含著的水煙管。"],["穿西裝的觀眾","坐在右邊的西裝男子，應是世博會的遊客。"],["茶杯托盤","桌下的小茶杯。"],["圓頂與塔","背景中為世博會建造的突尼西亞風格建築。"],["標題","「TUNISIE」和「PARTIE DE CARTES DEVANT UN CAFÉ ARABE」。"]]},"laghouat":{"title":"拉格瓦特附近的卡伊德們","artist":"佚名","date":"1880—1890年","place":"阿爾及利亞（拉格瓦特附近）","game":"應為骨牌","medium":"蛋白照片","size":"20.9×27.0公分","credit":"","p":["這張照片題為「阿爾及利亞人——拉格瓦特附近的卡伊德們」，貼在相簿裡，印有編號「239」。卡伊德是法國統治下阿爾及利亞地方首領的稱呼。","穿白袍的男人們坐在土牆前的蓆子上，在矮桌上擺著長條形的牌。從擺法看應是骨牌，但美術館記錄只寫著「遊戲」。前面放著茶盤和脫下的鞋子。"],"spots":[["矮桌上的牌","在桌上排成一列的長條牌。"],["茶盤","前面托盤裡的茶杯和壺。"],["脫下的鞋","放在蓆子外的鞋。"],["後面站著的人","靠牆站著看的人。"],["土牆","背後粗糙的土牆。"],["蓆子","男人們坐著的編織蓆。"]]},"hangong":{"title":"漢宮春曉圖（局部）","artist":"仇英（摹本）","date":"清代（1644—1911年）","place":"中國","game":"圍棋","medium":"手卷，絹本設色","size":"36.2×454.4公分（全卷）","credit":"","p":["這是清代臨摹明代畫家仇英（1494—1552年）構圖的手卷的一部分，全卷長四米半以上。春日的宮苑裡，宮女、少女和侍女們盪鞦韆、遊戲、賞牡丹、奏樂、撫琴、餵鸚鵡和魚，畫面由右向左展開。","這一段裡，欄杆後的兩位女子隔著棋盤對坐，其他人探身觀看。前面是放著太湖石的蓮花形石盆，侍女們抱著樂器和包裹走過。正如美術館所說，這幅畫把深宮女子的生活畫得十分理想化。"],"spots":[["棋盤","欄杆後桌上的圍棋盤。"],["落子的女子","伸手向棋盤的淡紫衣女子。"],["觀棋的女子們","俯身看棋局的女子們。"],["執團扇的女子","柱間拿著團扇的女子。"],["太湖石","安放在蓮花形盆裡的青色奇石。"],["抱樂器的侍女","抱著應是琵琶的樂器行走的侍女。"]]},"homerbg":{"title":"雙陸","artist":"溫斯洛·霍默","date":"約1877年","place":"美國","game":"雙陸（西洋雙陸）","medium":"木口木刻","size":"","credit":"","p":["這是根據美國畫家溫斯洛·霍默（1836—1910年）的畫刻成的木口木刻。霍默年輕時當過雜誌插畫家，為這類版畫畫過許多畫。下方印著「396.—BACKGAMMON.—WINSLOW HOMER.」，應是書或雜誌中帶編號的一頁。","兩位女子在有裝飾的沙發上相對而坐，在搭在膝上的棋盤上玩西洋雙陸。棋盤上有一個白色圓形物，是什麼並不清楚。長裙的褶子和沙發捲曲的扶手都用細線刻成。"],"spots":[["棋盤","搭在兩人膝上的棋盤。"],["左邊的女子","挽著頭髮、伸手向棋盤的女子。"],["右邊的女子","探身看棋盤的女子。"],["沙發扶手","捲渦形的扶手。"],["裙子","用細線刻出的長裙褶子。"],["標題","下方的「396.—BACKGAMMON.—WINSLOW HOMER.」。"]]},"chessst":{"title":"下西洋棋的男女（立體照片）","artist":"佚名","date":"1852—1858年","place":"不詳","game":"西洋棋","medium":"立體照片（上色）","size":"8.3×16.5公分","credit":"","p":["這是英語稱為「The Chess Players（下棋的人）」的一對立體照片。用立體鏡觀看，棋盤和棋子彷彿浮到眼前。黑白照片上給紅色帷幕和黃色衣裙上了顏色。","穿黃衣的女子手搭在棋子上，對面的男子背對著我們盯著棋盤。棋盤上有紅白兩色棋子，看似正在對局，但應是照相館裡佈置的場面。19世紀中葉，這類家庭情景的立體照片銷售很廣。"],"spots":[["棋盤與棋子","方格棋盤上的紅白棋子。"],["移動棋子的手","女子把手搭在棋子上。"],["女子","白領黃衣的女子，低頭看棋盤。"],["男子","背對我們坐著的男子。"],["紅色帷幕","背景中上了色的帷幕。"],["另一張","右邊的照片，兩張用立體鏡看就有縱深。"]]},"corrida":{"title":"鬥牛骰子遊戲（Corrida de Toros）","artist":"何塞·瓜達盧佩·波薩達","date":"1898年","place":"墨西哥","game":"擲骰賽跑遊戲（兩枚骰子，下注）","medium":"照相凸版·布紋紙","size":"40.4×30.0公分","credit":"","p":["這是波薩達繪圖的賽跑遊戲，題為「CORRIDA DE TOROS（鬥牛）」。格子排成螺旋，從外圈的1號向中心，依次畫著鬥牛的招式和場面。中心是鬥牛場建築，下方印著安東尼奧·瓦內加斯·阿羅約印刷所的名字。","據下方的「說明」，兩人以上各出賭注，擲兩枚骰子前進。例如5號「撐竿跳」前進到10，12號「長矛手被牛頂」要付錢並停走，28號「胸前過牛」要從頭開始。到達32號「拖走公牛」的人拿走全部賭注。"],"spots":[["標題","「CORRIDA DE TOROS」字樣。"],["鬥牛場","螺旋中心的鬥牛場建築。"],["1號格","螺旋入口的起點格。"],["牛頭","右上角有角的牛頭。"],["鬥牛士","左下的鬥牛士肖像。"],["說明","下方的「EXPLICACION」文字。"]]},"ambrocards":{"title":"打牌的三個男人","artist":"佚名（美國）","date":"1865年","place":"美國","game":"紙牌","medium":"玻璃底片照片（安布羅式）","size":"14.0×11.0公分","credit":"","p":["安布羅式照片是把拍在玻璃板上的薄負片背面塗黑，使它看起來像正片的照片。它比達蓋爾銀版便宜，在1850—60年代的美國很流行。這張裝在鍍金框裡，放在襯紅天鵝絨的盒子中。","素色背景前，三個男人圍著小桌，手裡拿著牌。左邊的人戴圓頂禮帽，右邊的人戴便帽，兩人都叼著雪茄；中間穿深色外套的人看著我們。應是為了拍照，擺出牌局進行中的姿勢。"],"spots":[["手牌","在桌上拿著牌的手。"],["戴禮帽的男人","左邊叼雪茄的人。"],["中間的男人","穿深色外套、看著我們的人。"],["戴便帽的男人","右邊叼雪茄的人。"],["鍍金框","圍著影像的壓花鍍金框。"],["盒子","襯紅天鵝絨的盒子。"]]},"morphy":{"title":"西洋棋冠軍保羅·墨菲","artist":"溫斯洛·霍默","date":"1859年","place":"美國","game":"西洋棋","medium":"木口木刻","size":"","credit":"","p":["這是下方印著「PAUL MORPHY, THE CHESS CHAMPION」的肖像木口木刻，依據當時還是年輕插畫家的霍默（1836—1910年）的畫刻成。墨菲（1837—1884年）是紐奧良出身的棋手，1858—59年巡遊歐洲，接連擊敗一流高手，載譽回國。","年輕的墨菲坐在椅子上，左手放在棋盤邊，旁邊立著國王、城堡、士兵等棋子。這是他歸國成為話題人物的1859年之作，應是作為報刊插圖印行的。"],"spots":[["棋子","棋盤上的國王、城堡、士兵等。"],["放在棋盤上的手","搭在棋盤邊的左手。"],["墨菲的臉","剛過二十歲的年輕冠軍。"],["領結","衣著整齊的領口。"],["膝上的手","放在膝上的右手。"],["標題","下方的「PAUL MORPHY, THE CHESS CHAMPION」。"]]},"dutton":{"title":"舍伯恩莊園客廳裡的達頓一家","artist":"約翰·佐法尼","date":"約1772年","place":"英國","game":"紙牌","medium":"布面油畫","size":"101.5×127.0公分","credit":"","p":["這是生於德國、在英國成名的畫家佐法尼（1733—1810年）的作品。以輕鬆姿態描繪家庭的「談話畫」誕生於18世紀的英國，十分流行。場景是格洛斯特郡舍伯恩莊園的客廳。","據美術館介紹，父親和女兒、母親和兒子正在紙牌遊戲中盤算下一手怎麼出。這家人剛失去一位親人，所以父母穿著全喪的黑衣，子女穿著輕喪的淡紫、白色和灰色。"],"spots":[["牌桌","鋪綠布的桌子和紙牌。"],["父親","穿黑衣拿著牌的父親。"],["女兒","穿白衣看牌的女兒。"],["兒子","穿灰衣拿著牌的兒子。"],["母親","穿黑色喪服的母親。"],["壁爐","生著火的大理石壁爐。"]]},"whist":{"title":"聖誕節的學者們——惠斯特聯合遊戲","artist":"詹姆斯·布雷瑟頓（應據H. W. 班伯里原畫）","date":"1773年","place":"英國","game":"惠斯特（紙牌）","medium":"蝕刻版畫","size":"26.5×39.6公分","credit":"","p":["據美術館說，這是諷刺劍橋大學學者的漫畫。左下可讀出「H. W. 班伯里繪 1772」，右下是「J. 布雷瑟頓刻」，1773年由倫敦新龐德街的店出版。牆上掛著學者的方帽。","四位紳士一邊打惠斯特紙牌，一邊互相做鬼臉。惠斯特是兩人一組對抗的遊戲，標題裡的「聯合遊戲」應是雙關。後面有人在別人頭上豎起手指捉弄他。旁邊還有兩個僕人和兩隻狗。"],"spots":[["桌上的牌","出在桌上的牌。"],["戴假髮的學者","戴著大假髮、把手牌貼在胸前的學者。"],["豎手指的人","在別人頭上豎起手指的人。"],["女僕","戴帽子、端著托盤的僕人。"],["方帽","掛在牆上的大學方帽。"],["右邊的狗","右下吠叫的小狗。"]]},"hey":{"title":"下棋的三個男人","artist":"保羅·海","date":"1877—1952年","place":"德國","game":"西洋棋","medium":"版畫（應為蝕刻）","size":"19.3×26.0公分","credit":"","p":["這是德國畫家、插畫家保羅·海（1867—1952年）的版畫。三位老人湊在桌邊，盯著同一副棋盤。細線層層疊加，畫出深深的皺紋和白鬍子。","正如美術館記錄所說，左邊的人手托下巴，右邊的人指間夾著雪茄，把手伸向棋子。桌子左邊有兩隻咖啡杯、一個玻璃杯和一盒火柴。這應是在咖啡館裡下的一盤棋。"],"spots":[["棋盤","桌上的棋盤和棋子。"],["托腮的人","白鬍子的老人，手托下巴沉思。"],["中間的人","探身伸手拿棋子的人。"],["右邊的人","從後面探頭看的人。"],["夾雪茄的手","指間夾著雪茄的手。"],["咖啡和火柴","左邊的兩隻杯子、玻璃杯和火柴盒。"]]},"artful":{"title":"狡猾的一張牌，奶奶多輸一張（紅心是王牌！）","artist":"佚名","date":"1852—1863年","place":"應為英國","game":"紙牌","medium":"立體照片（上色）","size":"8.4×17.4公分","credit":"","p":["英文標題是「The artful card, or, one too many for granny. Hearts are trumps!」。這是把用狡猾的牌贏過奶奶的滑稽小場面做成一對立體照片。從英文標題看，應是英國製作的。","圓桌邊奶奶和小女孩在打牌，穿綠衣的姑娘拿著手牌，被身後的年輕男子摟著肩。「紅心是王牌」應是把紙牌的紅心和戀愛之心雙關。有紡車和碗櫃的房間，大概是照相館的布景。"],"spots":[["姑娘的手牌","綠衣姑娘拿在胸前的牌。"],["年輕男子","從後面把手搭在姑娘肩上的男子。"],["奶奶","戴頭巾、低頭看牌的老婦人。"],["小女孩","笑著出牌的小女孩。"],["桌子","放著牌和小物的圓桌。"],["碗櫃","玻璃門裡擺著器皿的櫃子。"]]},"cezcards":{"title":"玩牌者習作","artist":"保羅·塞尚","date":"1890—92年","place":"法國","game":"紙牌","medium":"水彩、鉛筆·米色紙","size":"36.2×48.5公分","credit":"","p":["1890年代，塞尚在法國南部的艾克斯畫了好幾幅玩牌的男人。這是為那組畫作的水彩習作：戴帽子、留著小鬍子的男人坐在桌前看手裡的牌。","在鉛筆線上薄薄疊上藍色和灰色水彩，抓住了外衣的褶皺和身體的分量。右邊和桌子遠端留著未完成，只在人物周圍上了色。據說模特是當地的勞動者。"],"spots":[["男人的臉","帽簷下垂著眼看牌。"],["手牌","雙手拿著的紙牌。"],["桌子","只用鉛筆線畫的桌子。"],["椅子","左邊的椅背。"],["外衣","疊著藍灰色的衣褶。"],["未完成處","桌腳附近只留著線條。"]]},"vuillardck":{"title":"跳棋對局（《風景與室內》之一）","artist":"愛德華·維亞爾","date":"1899年","place":"法國","game":"跳棋（國際跳棋）","medium":"彩色石版畫·灰象牙色紙","size":"36.9×28.5公分","credit":"","p":["這是法國畫家維亞爾的彩色石版畫集《風景與室內》的第一幅，由畫商安布魯瓦茲·沃拉爾出版，石版印刷師奧古斯特·克洛印製。","在滿是花紋壁紙的房間裡，一位留鬍子的男人對著跳棋盤，一位穿格子裙的女子站著托腮看棋。人物、壁紙和沙發都融成平塗的色塊和圖案，只有棋盤的黑白格清晰地浮現出來。"],"spots":[["棋盤","黑白相間的跳棋盤。"],["留鬍子的男人","對著棋盤的男人。"],["站著的女子","穿格子裙、托著下巴的女子。"],["壁紙","佈滿捲曲線條的壁紙。"],["花紋靠墊","左下的花紋布料。"],["燈","靠牆的細長燈形。"]]},"cruikchess":{"title":"西洋棋對局","artist":"喬治·克魯克香克（據弗雷德里克·馬里亞特上尉原稿）","date":"1814年","place":"英國","game":"西洋棋","medium":"手工上色蝕刻版畫","size":"23.8×34.5公分","credit":"","p":["這是英國諷刺畫家克魯克香克根據海軍軍官、後來成為小說家的馬里亞特的草圖刻成的版畫，由倫敦的漢娜·漢弗萊出版。下方印著標題「GAME of CHESS」。","點著蠟燭的桌邊，兩位老紳士對著棋盤。兩人身後各站著一個看客：左邊的把手指放在嘴邊示意「安靜」，右邊的舉著帶柄眼鏡湊近看棋。這應是在取笑忍不住插嘴的看客。"],"spots":[["棋盤","擺著黑白棋子的棋盤。"],["蠟燭","照亮棋盤的兩支蠟燭。"],["示意安靜的人","手指放在嘴邊的看客。"],["拿眼鏡的人","舉著帶柄眼鏡看棋的看客。"],["睡著的狗","桌下睡覺的狗。"],["標題","下方的「GAME of CHESS」。"]]},"domino98":{"title":"在桌邊玩骨牌的女子與孩子","artist":"佚名（美國）","date":"約1898年","place":"美國","game":"骨牌","medium":"蛋白照片（貼在玻璃上）","size":"40.8×51.1公分","credit":"","p":["這是一張應出自美國照相館的大幅照片，貼在玻璃板上裝成。穿白衣的女子和捲髮的小女孩隔著插著花的小桌坐著。","桌上擺著骨牌，女子正拿著一枚往下放。小女孩托著腮注視著。窗簾、裝飾櫃和掛畫的牆，應是照相館的佈景。"],"spots":[["骨牌","桌上排著的白色骨牌。"],["小女孩","托腮看骨牌的女孩。"],["女子","穿白衣、放下骨牌的女子。"],["花","桌上花瓶裡的花。"],["裝飾櫃","右後方華麗的櫃子。"],["題字","右下的白色字樣。"]]},"langkat":{"title":"在船上打牌的阿爾伯特·格拉澤和朋友們（蘇門答臘，朗加特）","artist":"佚名（H. 恩斯特公司）","date":"1895—1905年","place":"印尼（蘇門答臘島，朗加特）","game":"紙牌","medium":"照片","size":"17.5×22.8公分","credit":"","p":["這是在蘇門答臘島北部朗加特拍攝的照片。右下有照相館「H. Ernst & Co. / Bindjey Langkat」的壓印，背面手寫著中間的人是阿爾伯特·格拉澤，是某位夫人的兄弟。","在搭著遮陽棚的船甲板上，三個穿白衣的男人圍著桌子拿著牌。桌上放著牌和像硬幣的小東西，右邊男人身旁有個瓶子。白衣和遮陽棚透露出炎熱地方的生活。"],"spots":[["桌上","發好的牌和像硬幣的小東西。"],["格拉澤","中間展開手牌的人，背面寫著他的名字。"],["左邊的男人","半背對著、拿著牌的男人。"],["右邊的男人","留鬍子、拿著牌坐在桌邊的男人。"],["瓶子","右邊男人身旁的瓶子。"],["遮陽棚","從棚頂垂下的葉飾和遮陽棚。"]]},"chatur":{"title":"恰圖蘭卡對局","artist":"佚名","date":"1805—1815年","place":"印度","game":"恰圖蘭卡","medium":"水粉、金，毛筆","size":"16.2×9.8公分（畫面）","credit":"","p":["這是一幅印度細密畫。據美術館記錄，兩位女子在玩一種叫恰圖蘭卡的棋戲，侍女拿著拂塵。恰圖蘭卡是印度古老的棋戲，被視為西洋棋的祖先。","白色拱柱下的紅毯上，穿深藍衣和穿橙衣的女子隔著格子棋盤相對而坐。穿橙衣的女子伸出手，像是在說話。畫面四周圍著一圈用黑白線勾邊的深紅框。"],"spots":[["棋盤","紅毯上的格子棋盤。"],["深藍衣女子","戴著金飾、伸手向棋盤的女子。"],["橙衣女子","伸出手與她相對的女子。"],["侍女","站在後面的侍女。"],["拂塵","侍女舉著的拂塵。"],["紅框","黑白線勾邊的深紅框。"]]},"shabbarat":{"title":"女眷居所之夜","artist":"佚名","date":"1760—1770年","place":"印度","game":"喬帕爾（帕奇西）","medium":"水粉、金，毛筆","size":"34.3×25.6公分","credit":"","p":["這是一幅印度細密畫。據美術館記錄，四位女子在宮殿寬敞的庭院裡玩棋戲，這種遊戲叫喬帕爾或帕奇西。她們圍坐在十字形的布棋盤旁。","前排右邊的女子手持三根長條骰子，正要擲出。她旁邊倚著靠枕的是地位最高的女子。雖是夜晚，露臺上處處放著燈，遠處城牆上也點著無數燈火。記錄認為，這裡可能在慶祝伊斯蘭節日「拜拉特夜」。"],"spots":[["十字形棋盤","鋪在地上的十字形棋盤。"],["拿骰子的女子","前排手持長條骰子的女子。"],["倚靠枕的女子","地位最高的女子。"],["侍女","端著托盤走來的女子。"],["燈","玻璃罩裡燃著的蠟燭。"],["遠處的亭子","有噴泉的庭園、亭子和城中燈火。"]]},"govase":{"title":"仕女弈棋圖卵形瓶","artist":"佚名（「唐金堂」印）","date":"1724年","place":"中國（廣東）","game":"圍棋","medium":"瓷器，釉上彩（粉彩）、描金","size":"高15.3公分","credit":"","p":["這是一只用極薄瓷胎、釉上彩繪製的中國花瓶。背面題有「博弈圖，甲辰花朝寫於嶺南珠江精舍」，並有紅印「唐金堂」。它是海牙收藏家羅耶爾瓷器收藏中的一件。","兩位女子隔著桌上的棋盤對坐，左邊的女子手持棋罐。右邊有兩位女子和兩個孩子探身觀看。後面的几案上陳設著插孔雀翎的花瓶、珊瑚等古玩。"],"spots":[["棋盤","桌上的棋盤和黑白棋子。"],["左邊的棋手","拿著棋罐、伸指的女子。"],["右邊的棋手","俯身向棋盤的女子。"],["觀棋的女子們","從後面探看棋局的女子們。"],["孔雀翎與珊瑚","几案花瓶裡的孔雀翎和珊瑚。"],["棋罐","左邊女子手裡的棋罐。"]]},"yokihi":{"title":"唐玄宗與楊貴妃雙陸","artist":"佚名（摺物）","date":"1822年","place":"日本","game":"盤雙六（雙陸）","medium":"多色木版畫，金屬顏料","size":"21.6×19.1公分","credit":"","p":["摺物是把畫與狂歌等詩配在一起、用厚紙和金屬粉奢華印製的版畫，由詩人們訂製，作為送給同好的禮物。這一張印著一首狂歌和詩人名「橘五園」。","據美術館記錄，畫的是唐玄宗（685—762年）與寵妃楊貴妃（719—756年）玩雙六，這種遊戲與西洋雙陸、特里克特拉克同類。紅色小台上放著箱形棋盤，上面排著黑白棋子。"],"spots":[["棋盤","紅台上的箱形雙六盤和棋子。"],["楊貴妃","頭戴花飾、手放在棋盤上的楊貴妃。"],["玄宗","手托下巴看棋盤的玄宗。"],["狂歌","左上的一首詩和詩人名。"],["屏風","後面畫著山的屏風。"],["署名與印","右下的署名和朱印。"]]},"disderi":{"title":"穿水手服裝打牌的男人們","artist":"迪斯德里公司","date":"1850—1890年","place":"法國（巴黎）","game":"紙牌","medium":"蛋白照片（名片照）","size":"8.6×5.3公分","credit":"","p":["這張名片照貼在相簿裡，背面印著巴黎「迪斯德里公司（義大利人大道8號）」。迪斯德里就是推廣了「名片照」——像名片一樣一次印很多張的小照片——的攝影師。","戴三角帽、穿長外衣和白襪子的舊式打扮的男人們，圍著有花紋的桌子打牌。美術館記錄說是「水手服裝」，但應是演戲或化裝用的服裝。中間的男人站起來探看桌面。"],"spots":[["桌子","有花紋邊飾的桌子，上面有牌和杯子。"],["站起來的男人","戴三角帽、探身看桌子的男人。"],["左邊的男人","拿著牌坐著的男人。"],["右邊的男人","戴三角帽、拿著牌的男人。"],["帶扣的鞋","白襪和帶扣的鞋。"],["金框","圍著照片的襯板金框。"]]},"gans":{"title":"鵝棋（74格螺旋）","artist":"揚·奧爾特曼（父），據丹尼爾·威廉·斯托彭達爾設計","date":"1763—1823年","place":"荷蘭","game":"鵝棋（擲骰賽跑遊戲）","medium":"木刻（藍、紅、綠著色）","size":"40.8×46.8公分","credit":"","p":["這是一張在荷蘭印製的螺旋形賽跑棋盤。據美術館說，格子從1排到74，有些格子裡有圖。刻版的是揚·奧爾特曼，設計者斯托彭達爾的名字帶著「invenit（設計）」印在右下角。","終點74是中央夕陽下海邊的神殿。格子裡寫著「LEER GELD（學費）」「DWAALWEG（歧路）」「DOMHEID / WYSHEID（愚蠢／智慧）」等詞，還有拿大鐮刀的骷髏「EINDE（終結）」，應是講人生道路的教訓遊戲。"],"spots":[["74：神殿","終點神殿，立在夕陽下的海邊。"],["1：起點","左下第一格。"],["學費","「LEER GELD」格，應是停在這裡要付錢。"],["歧路","寫著「DWAALWEG」的林間小路。"],["終結","拿大鐮刀的骷髏「EINDE」。"],["骰子","畫著兩顆骰子的格子。"]]},"merelle":{"title":"梅雷爾棋與風箏","artist":"克洛迪娜·斯特拉（據雅克·斯特拉原畫）","date":"1657年","place":"法國（巴黎）","game":"梅雷爾（九子棋）","medium":"雕版畫","size":"11.7×14.1公分","credit":"","p":["這是畫家雅克·斯特拉設計、由他的姪女克洛迪娜刻成的兒童遊戲系列的第17幅。據美術館說，它出自一本裝訂了51幅版畫的冊子。玩耍的是胖嘟嘟的裸體小孩（普托）。","左前方，孩子們在石台上刻出的棋盤上下「梅雷爾」（九子棋）。右邊地上畫著方格和對角線，是往方格裡扔硬幣的「方格擲幣」遊戲，遠處一個孩子拉著風箏奔跑。下面的詩說，每種遊戲大家都玩得很用心。"],"spots":[["梅雷爾棋盤","刻在石台上的棋盤和棋子。"],["風箏","高高飛著的風箏。"],["放風箏的孩子","拉著線奔跑的孩子。"],["方格擲幣","地上畫的方格和對角線。"],["指著的孩子","手拿東西、指著地上線條的孩子。"],["標題","「LA MERELLE, & LE CERF VOLANT」字樣。"]]},"feldcards":{"title":"在花園桌邊打牌的人們（立體照片）","artist":"佚名","date":"1850—1880年","place":"不詳（背面有格羅寧根店鋪印章）","game":"紙牌","medium":"蛋白照片（立體照片）","size":"8.5×17.0公分","credit":"","p":["這張立體照片拍的是在常春藤爬滿格子籬的花園裡，像是一家人或朋友們圍桌打牌。背面蓋著荷蘭格羅寧根「費爾特布呂赫公司」的印章，應是出售它的店鋪或出版商。","左邊留鬍子的男人高高舉起一張牌，好像馬上要拍到桌上。托著腮的男人、拿著牌的少年、白髮老人和在後面看著的女子，一起留下了牌局的一瞬間。因為大家必須長時間不動，這應是擺好姿勢的場面。"],"spots":[["舉起的牌","留鬍子的男人高舉的一張牌。"],["桌上","已經出到桌上的牌。"],["少年的手牌","背對我們的少年拿著的牌。"],["白髮老人","坐在右邊的老人。"],["看著的女子","站在後面看牌局的女子。"],["刺繡椅子","前面蒙著花布的椅子。"]]},"tempel":{"title":"遊戲盤《幸運神殿》","artist":"佚名","date":"1816年","place":"荷蘭","game":"擲骰賽跑遊戲","medium":"木刻，活字印刷文字","size":"43.0×48.5公分","credit":"","p":["這是一張1到74格呈螺旋排列的遊戲單頁。中央畫著海邊的圓形神殿；同一收藏中保存的規則紙稱它為「幸運神殿」，並說這是一種「投擲遊戲」，也就是骰子遊戲。","大多數格子是空白圓圈，但也有玫瑰、荊棘、骰子、鐵門、渡船等圖，以及「LEER GELD（學費）」「DOMHEID（愚蠢）」「WYSHEID（智慧）」等字。這應是一種勸善的賽跑遊戲，經過善行與惡行，奔向神殿。"],"spots":[["幸運神殿","中央海邊的神殿，是終點74號。"],["1號格","從左下開始的起點。"],["學費","寫著「LEER GELD」的格子。"],["骰子","上排畫的兩枚骰子。"],["渡船","下排「OVER HAAL（擺渡）」的圖。"],["愚蠢與智慧","右邊的「DOMHEID」「WYSHEID」。"]]},"verkeer":{"title":"微型盤（費爾凱爾棋盤）","artist":"佚名","date":"1690—1710年","place":"荷蘭（阿姆斯特丹）","game":"費爾凱爾（雙陸的一種）、西洋棋、九子棋","medium":"胡桃木，鑲橄欖木、烏木、黃楊木、骨，銅件","size":"合上5.8×5.8公分（展開11.6公分）","credit":"","p":["這是一件邊長僅約六公分、能像盒子一樣打開的遊戲盤。外面是西洋棋盤和九子棋盤，裡面是費爾凱爾（荷蘭的一種雙陸）的棋盤，用銅合頁和小鉤扣上。","裡面還留著一枚骰子、九枚骨棋子、四枚烏木棋子和三枚小硬幣。從美術館的編號看，它應是佩特羅內拉·奧爾特曼娃娃屋的陳設之一。雖然很小，木鑲嵌卻很精細，做法和真正的棋盤一樣。"],"spots":[["骰子","米粒大小的骰子。"],["骨棋子","白色的圓形骨棋子。"],["烏木棋子","黑色的烏木棋子。"],["三角格","明暗木料交替鑲嵌的三角。"],["合頁","對折用的銅合頁。"],["小鉤","扣上用的小銅鉤。"]]},"silverbd":{"title":"銀質微型棋盤與棋子","artist":"弗雷德里克·范·斯特蘭特二世","date":"1739年","place":"荷蘭（阿姆斯特丹）","game":"國際跳棋、九子棋","medium":"銀","size":"5.4×5.4公分","credit":"","p":["這是一件僅5.4公分見方的銀棋盤：64格的盤面，邊緣立起，並有掛環。深色格刻著細線，背面刻著九子棋的線。","上面打著阿姆斯特丹城徽、表示1739年的年代字母「E」，以及銀匠弗雷德里克·范·斯特蘭特二世的印記。隨盤留存著15枚跳棋子，8枚有花紋，7枚有圓圈紋。應是放在娃娃屋或陳列櫃裡的銀質微型器物。"],"spots":[["花紋棋子","壓出花紋的棋子。"],["圓紋棋子","有圓圈紋的棋子。"],["掛環","棋盤角上的環。"],["刻紋格","刻著細線的深色格。"],["光面格","打磨光滑的淺色格。"],["邊緣","棋盤四周立起的邊。"]]},"schaak1550":{"title":"騎馬棋子的西洋棋","artist":"佚名","date":"1550年","place":"德國","game":"西洋棋","medium":"黃楊木、針葉木","size":"最大棋子高10.5公分","credit":"","p":["每枚棋子都立在旋製的底座上，四周圍著花飾欄杆，上面雕著人物和馬。國王和王后騎著馬或騾，像是要去打獵。","據美術館記錄，黑方國王騎著一匹踏著龍、後腿直立的馬，頸上掛著讓人想起金羊毛騎士團的鏈子，或許表示他是查理五世。王后側坐在騾上，手上停著鷹。最右邊還有一枚滑稽的棋子：猴子騎在人背上。"],"spots":[["國王","戴冠、留鬚的騎馬國王。"],["王后","側坐騎騾、手托獵鷹的王后。"],["猴子棋子","騎在人背上的猴子。"],["滑稽的棋子","最左邊一人騎在另一人背上。"],["腳下的生物","蹲在馬蹄下的龍和獸。"],["底座","圍著花飾欄杆的旋製底座。"]]},"kraaij":{"title":"在客廳玩棋的男女","artist":"佚名","date":"1900—1910年","place":"應為荷蘭","game":"雙陸（西洋雙陸）","medium":"日光顯影珂羅酊銀鹽照片","size":"8.0×11.1公分","credit":"","p":["這是某個家庭相簿中的一張，相簿裡還有葡萄酒商「克賴公司（波爾多—阿姆斯特丹）」的照片。在掛著吊燈的客廳裡，像是家人或熟人的男女圍坐在桌邊。","桌上打開著折疊式的盒形棋盤，左右兩位女子各拿著骰盅。美術館記錄寫的是「棋戲」，但從盒形棋盤和骰盅看應是雙陸。旁邊有咖啡杯，後面有鳥籠，傳達出家中夜晚的悠閒。"],"spots":[["盒形棋盤","打開的折疊盒子做成的棋盤。"],["左邊的骰盅","戴眼鏡的女子拿著的骰盅。"],["右邊的骰盅","穿圓點衣服的女子正要搖的骰盅。"],["鳥籠","後面台子上的鳥籠。"],["吊燈","從天花板垂下的玻璃燈罩吊燈。"],["站著的男人","站在右邊俯看棋局的男人。"]]},"braekel":{"title":"下跳棋的老夫婦","artist":"費迪南德·德·布雷克萊爾（父）","date":"1862年","place":"比利時（安特衛普）","game":"跳棋","medium":"蝕刻版畫","size":"21.8×16.5公分","credit":"","p":["這是安特衛普畫家德·布雷克萊爾（1792—1883年）的蝕刻版畫，左下簽著「Ferdinand De Braekeleer Antwerpen 1862」。在有壁爐的舊廚房裡，一位老翁和一位老婦隔著小桌對坐。","桌上棋盤排著圓棋子，老翁拈起一枚，老婦張開手像在回嘴。地上放著帽子，也掉了幾枚棋子。架子上擺著盤子，窗外能看到房屋。"],"spots":[["棋盤與棋子","桌上的棋盤和圓棋子。"],["老翁","俯身拈起棋子的男人。"],["老婦","戴頭巾、張手說話的女人。"],["地上的帽子","放在地上的老翁的帽子。"],["簽名","「Ferdinand De Braekeleer Antwerpen 1862」。"],["架上的盤子","壁爐上方架子上的大盤子。"]]},"billiard":{"title":"撞球","artist":"據H. W. 班伯里原畫（刻者佚名）","date":"1780年","place":"英國（倫敦）","game":"撞球","medium":"蝕刻與點刻","size":"30.0×39.1公分","credit":"","p":["這是據英國漫畫家亨利·威廉·班伯里原畫製作的版畫，1780年由倫敦的沃森與迪金森店出版。據美術館說，是一套系列中的第4幅。","兩個男人在打撞球，周圍的人屏息觀看。一人探身在台上架起球桿，另一人把球桿扛在肩上。牆上有桿架和兩個計分用的圓盤。美術館說球台看起來像三角形。"],"spots":[["球台與球","鋪著布的球台和上面的球。"],["瞄準的人","探身在台上出桿的男人。"],["扛桿的人","拿著長桿等候的男人。"],["計分盤","牆上兩個圓盤，應是計分用具。"],["桿架","靠牆立著的一排球桿。"],["笑著的兩人","右邊湊在一起笑的觀眾。"]]},"baizi":{"title":"百子圖（局部）","artist":"徐揚宏","date":"18世紀","place":"中國","game":"圍棋","medium":"手卷，紙本水墨（淡設色）","size":"29.8×526公分（全卷）","credit":"","p":["這是從中國職業畫家徐揚宏所作、長五米多的手卷中截取的下棋場面。庭園裡一百個孩子在遊戲、奏樂、讀書、寫字。「百子」是亞洲藝術的重要題材，象徵多子多福、家族興旺。","這卷畫也因日本的谷文晁後來臨摹而聞名，摹本也藏於同一美術館。芭蕉和太湖石旁，孩子們圍著矮几上的棋盤，兩人拿著棋罐對弈，其他孩子探頭觀看。"],"spots":[["棋盤","矮几上的棋盤和棋子。"],["落子的孩子","穿藍衣、手伸進棋罐的孩子。"],["另一位棋手","俯身向棋盤的白衣孩子。"],["抱頭的孩子","在後面抱著頭看的孩子。"],["太湖石","滿是孔洞的大奇石。"],["羽扇","左邊拿羽扇的孩子。"]]},"schenkcards":{"title":"玩紙牌的兩位中國女子","artist":"彼得·申克（子）","date":"1727—1775年","place":"荷蘭（題材為中國）","game":"紙牌","medium":"蝕刻版畫","size":"16.5×26.2公分","credit":"","p":["這是阿姆斯特丹出版商兼版畫家小彼得·申克出版的中國風人物與風景版畫集《新創中國人》第一部中的一頁。這是歐洲流行的「中國風」版畫，畫的是想像中的中國。","據美術館記錄，兩位中國女子在庭園裡玩紙牌，右邊一位女子端著盛滿食物的托盤走來。桌上的牌看起來像歐洲的撲克牌。左邊台子上臥著一隻兔子，河上漂著一艘帆船。"],"spots":[["桌上的牌","鋪在桌上的紙牌，看來像歐洲的牌。"],["左邊的女子","拿著牌看著對手的女子。"],["右邊的女子","把牌放到桌上的女子。"],["端托盤的女子","端著盛滿食物的托盤的女子。"],["兔子","臥在左邊台子上的兔子。"],["帆船","河上的帆船。"]]},"gosaucer":{"title":"弈棋人物圖盤","artist":"佚名","date":"1725—1735年","place":"中國","game":"圍棋","medium":"瓷器，釉上彩（粉彩）、描金","size":"口徑16.4公分","credit":"","p":["這是一只用柔和的釉上彩「粉彩」繪製的中國盤子。底部畫著用雙圈圍起的筆、如意和墨錠標記。美術館的記錄有的說是「一男一女下棋」，有的說是「三位女子中兩人下棋」，對人物的看法不一。","屋內桌上放著棋盤，兩人相對落子，另一人站在後面觀看。桌上有黃色棋罐，後面是放花瓶的几架，右邊畫著一只大青罐。"],"spots":[["棋盤","桌上的棋盤和棋子。"],["左邊的棋手","穿淡紫衣、倚著桌子的人。"],["右邊的棋手","穿粉衣落子的人。"],["觀棋的人","站在後面觀看的人。"],["花瓶","几架上的插花瓶。"],["青罐","右邊的大罐。"]]},"cheetham":{"title":"小小的紙牌聚會（在俄國）","artist":"佚名","date":"1903—1904年","place":"俄國","game":"紙牌","medium":"日光顯影明膠銀鹽照片","size":"9.2×11.5公分","credit":"","p":["這張照片來自住在俄國的英國奇瑟姆家族的相簿，襯紙上用英語寫著「a little card-party（小小的紙牌聚會）」。美術館記錄說，照片裡的人大概是來拜訪約瑟夫·奇瑟姆的英國朋友。","在貼著壁紙的房間裡，三個人圍著鋪花紋桌布的桌子，展開手牌。桌上立著兩座燭台，中間的女子把牌像扇子一樣打開，笑著。這應是在遙遠異鄉與同鄉朋友共度的輕鬆時光。"],"spots":[["左邊男人的手牌","留鬍子的男人展開的牌。"],["女子的手牌","中間的女子扇形展開的牌。"],["右邊的男人","探身拿著牌的男人。"],["燭台","桌上的兩座燭台。"],["桌布","有花和圖案的大桌布。"],["題字","襯紙上的「a little card-party」。"]]},"problem":{"title":"難題（下西洋棋的男女·立體照片）","artist":"佚名","date":"1852—1863年","place":"不詳","game":"西洋棋","medium":"立體照片（上色）","size":"8.4×17.4公分","credit":"","p":["英文標題是「The Problem（難題）」。兩位戴白色假髮、穿18世紀風格服裝的人在雕飾桌邊下棋，被做成上了色的一對立體照片。背面手寫著「Simons」。","年輕的一方雙手捧著臉頰盯著棋盤，對面的年長男子則咧嘴笑著。這應是一眼就能看出誰遇到難題的、像戲劇一樣的場面。腳邊趴著一隻狗。"],"spots":[["棋盤與棋子","雕飾桌上的棋盤和棋子。"],["苦思的人","雙手捧著臉頰盯著棋盤的人。"],["笑著的男人","穿藍色外衣、咧嘴笑的年長男子。"],["狗","趴在腳邊的狗。"],["紅色帷幕","背景中上了色的帷幕。"],["另一張","右邊的照片，用立體鏡看會有縱深。"]]},"tarocco":{"title":"塔羅牌中的十張","artist":"佚名（應據朱塞佩·瑪麗亞·米泰利設計）","date":"1660—1718年","place":"義大利（波隆那）","game":"塔羅基（塔羅牌遊戲）","medium":"蝕刻與雕版，部分用淺褐色手工上色","size":"貼在襯紙上的十張","credit":"","p":["這是從波隆那製作的一副塔羅牌中取出的十張牌，並排貼在襯紙上。塔羅牌起初不是用來占卜，而是用來玩有王牌的紙牌遊戲。上排最左是標題牌，美術館認為其中的肖像或許是畫家米泰利。","上排是戴冠的人、騎馬的人等四個人物，下排是「金幣」花色的6到10，每張印著相應數量的金幣。版畫的線條上，部分塗了淺褐色。"],"spots":[["標題牌","左上，有肖像畫框和題字的牌。"],["戴冠的男人","拿著權杖、戴冠的人物。"],["站著的女子","戴冠、手持杯子的女子。"],["騎馬的人","騎在馬上的人物牌。"],["金幣10","下排左邊，十枚金幣。"],["金幣6","下排右邊，六枚金幣。"]]},"kindtegel":{"title":"兒童遊戲磁磚","artist":"佚名","date":"1680—1730年","place":"荷蘭","game":"兒童遊戲（踩高蹺、盪鞦韆等）","medium":"錫釉陶器（台夫特磁磚），青色彩繪","size":"107×80公分（48塊）","credit":"","p":["這是由直8塊、橫6塊、共48塊磁磚拼成的一整面。每塊磚上用藍色小小地畫著兩個玩耍的孩子，四角各有一個叫作「蜘蛛」的小裝飾。","有踩高蹺的，有被人推著盪鞦韆的，有蹲在地上玩東西的，每塊磚畫的遊戲都不一樣。這類「兒童遊戲」磁磚在荷蘭很受歡迎，應是貼在廚房或壁爐周圍的牆上。"],"spots":[["高蹺","踩著高蹺的孩子。"],["鞦韆","被推著盪鞦韆的孩子。"],["地上的遊戲","蹲在地上擺弄東西的孩子。"],["蜘蛛紋","磁磚四角的小裝飾。"],["48塊的排列","直8塊、橫6塊的磁磚。"],["右下角的一塊","右下角的磁磚。"]]},"dammolen":{"title":"跳棋與九子棋兩用的微型棋盤","artist":"佚名","date":"1740—1760年","place":"荷蘭（阿姆斯特丹）","game":"國際跳棋、九子棋","medium":"胡桃木，淺色填料","size":"4.2×4.0×1.5公分","credit":"","p":["這是一塊寬約四公分的胡桃木小棋盤，近似正方形，邊緣立起。一面可作跳棋盤，另一面可作九子棋盤。","跳棋那面把格子刻出來再填入淺色填料，和木頭本色組成格紋；九子棋那面刻出的線也用同樣的填料填平。這麼小，應是為娃娃屋做的。"],"spots":[["填料格","刻出後填入淺色填料的格子。"],["木色格","保留胡桃木本色的格子。"],["邊緣","四周立起的邊。"],["近角","離我們最近的角。"],["厚度","高1.5公分的側面。"],["最裡一排","最裡面一排格子。"]]},"karelpiece":{"title":"刻有查理大帝像的跳棋子（半面）","artist":"佚名","date":"1525—1575年","place":"德國（紐倫堡）","game":"跳棋或雙陸","medium":"黃楊木","size":"直徑5.3公分","credit":"","p":["這是一枚黃楊木雕的跳棋子的一面。中央是月桂冠環繞的側面像，四周刻著「CAROLVS. MAGNVS. IMPER. AVGVST.（查理大帝，皇帝）」。","美術館藏有十幾枚同樣做法的棋子，分別刻著提比略、阿格里皮娜、虔誠者路易、奧托大帝等從古羅馬到中世紀的皇帝和皇后。應是把歷代君主做成一套棋子的奢華遊戲用具。"],"spots":[["側面像","月桂冠環繞的查理大帝側面像。"],["月桂冠","圍著肖像的月桂環。"],["CAROLVS","上方的「CAROLVS. MAGNVS」字樣。"],["AVGVST","左邊的「IMPER. AVGVST」字樣。"],["星","銘文間隔用的小星。"],["邊緣","棋子邊上的台階。"]]},"vdberge":{"title":"荷蘭的遊戲，美好生活！（打牌）","artist":"彼得·范登貝赫（設計並出版）","date":"1694—1737年","place":"荷蘭（阿姆斯特丹）","game":"紙牌","medium":"蝕刻（紅、藍、綠套色）","size":"27.3×17.0公分","credit":"","p":["這是阿姆斯特丹版畫家兼出版商范登貝赫的諷刺畫，題為「LE JEU HOLLANDOIS. LA BELLE VIE!」。據美術館說，酒館裡男人們在打牌，一個舉杯嘆氣的男人身邊和桌下，魔鬼們正贏走他的錢。","下方荷蘭語詩中，這個無憂無慮的浪蕩子哀嘆鬥狗、鬥雞、紙牌和骰子把他的錢花光了。兩側兩個魔鬼用德語引誘他：在骰子和紙牌上快活吧。後牆的畫上也畫著鬥狗和鬥雞。"],"spots":[["舉杯的男人","戴大假髮舉著酒杯的浪蕩子。"],["手牌","男人手裡展開的紙牌。"],["左邊的魔鬼","在他身後咧嘴笑的魔鬼。"],["桌下的魔鬼","摟走撒在地上的錢幣的魔鬼。"],["鬥狗鬥雞圖","牆上畫著鬥狗和鬥雞。"],["標題與詩","「LE JEU HOLLANDOIS」和浪蕩子的哀嘆詩。"]]},"crespi":{"title":"擲骰子的孩子們","artist":"朱塞佩·瑪麗亞·克雷斯皮","date":"1675—1747年","place":"義大利","game":"骰子","medium":"蝕刻版畫","size":"22.5×15.1公分","credit":"","p":["這是波隆那畫家克雷斯皮親手刻製的蝕刻版畫。據美術館說，四個孩子在街邊玩骰子，下面附有三行義大利語詩。","蹲著的孩子剛把骰子擲在地上，另外三人在旁觀看。詩裡說到骨頭（骰子）和數字、短暫的遊戲、錢越來越少，應是在孩子的遊戲裡也寄寓了對賭博的告誡。"],"spots":[["骰子","滾在地上的小骰子。"],["蹲著的孩子","剛擲出骰子的孩子。"],["站著的孩子","俯身探看的孩子。"],["右邊的孩子","坐在地上看著的孩子。"],["後面的孩子","從別人身後探出頭的孩子。"],["詩","三行義大利語詩。"]]},"epinal":{"title":"大鵝棋（埃皮納勒版）","artist":"佩爾蘭公司（埃皮納勒）","date":"1791—1900年","place":"法國（埃皮納勒）","game":"鵝棋（擲骰賽跑遊戲）","medium":"木刻（黃、紅、綠、藍著色），活字印刷文字","size":"39.8×59.0公分","credit":"","p":["這是法國東部埃皮納勒的佩爾蘭版畫工坊印製的彩色單頁，上方用法語寫著「GRAND JEU DE L’OIE」。據美術館說，63格螺旋裡畫著鵝、其他動物和人物，中央印著荷蘭語標題「GANZENBORD!」和玩法。","據玩法，擲兩枚骰子，停在鵝的格子可以再前進同樣的步數。6號橋去12，19號客棧停兩輪，31號井要等到別人來，42號迷宮退回30，58號死亡回到起點。必須正好到達63才算贏。左右兩邊排著可剪下用的籌碼。"],"spots":[["63：鵝","終點63，池上的鵝。"],["玩法","中央印的荷蘭語規則。"],["剪下的籌碼","兩側帶數字的圓形籌碼。"],["標題","上方的「GRAND JEU DE L’OIE」。"],["玩耍的孩子","左下角玩耍的孩子們。"],["工坊名","左上的「PELLERIN & Cie」。"]]},"matham":{"title":"玩特里克特拉克的男女","artist":"雅各布·馬塔姆（出版），西蒙·索維烏斯作詩","date":"1621年","place":"荷蘭（哈勒姆）","game":"特里克特拉克（雙陸的一種）","medium":"雕版畫","size":"17.9×20.0公分","credit":"","p":["這是哈勒姆版畫家兼出版商馬塔姆出版的四幅一套系列中的第3幅。據美術館說，衣著華麗的男女在房間的小桌上玩特里克特拉克並下注；桌上放著錢袋，女子手裡拿著骰子。","棋盤上細長的三角格和黑白棋子刻得清清楚楚。下面有拉丁語和荷蘭語詩，荷蘭語詩告誡說：不只是飲酒過度會擾亂心神，遊戲和賭博也有違一切利益。後面一個少年舉著葡萄酒杯。"],"spots":[["棋盤","排著三角格和棋子的特里克特拉克棋盤。"],["走棋的男人","戴帽子、伸手到棋盤上的男人。"],["拿骰子的女子","大領子的女子，手拿骰子。"],["舉杯的少年","後面舉著葡萄酒杯的少年。"],["錢袋","桌上裝賭注的錢袋。"],["詩","拉丁語和荷蘭語的告誡詩。"]]},"jardin":{"title":"在花園桌邊打牌的三個男人和旁觀者（法國）","artist":"佚名（法國業餘攝影師）","date":"1900—1910年","place":"法國","game":"紙牌","medium":"蛋白照片","size":"11.8×17.2公分","credit":"","p":["這張照片來自一位法國業餘攝影師的相簿，相簿裡還有家人、蒸餾酒公司「德利齊與杜瓦斯托」、軍隊和法國各地名勝的照片。","在鋪著礫石的花園樹蔭下，三個男人圍著小桌打牌，一位白鬍子的年長男子站在後面觀看。桌上放著牌，戴硬草帽的男人盯著手牌。這應是家人或朋友間輕鬆的一幕。"],"spots":[["桌上的牌","已經出到桌上的牌。"],["旁觀者","白鬍子的年長男子，從後面看牌局。"],["戴草帽的男人","中間盯著手牌的男人。"],["右邊的男人","穿深色外衣、拿著牌的男人。"],["左邊的男人","穿淺色上衣的男人。"],["花園","鋪礫石的花園和樹叢。"]]},"lamplight":{"title":"打牌的人們（燈下）","artist":"佚名","date":"1900—1910年","place":"不詳","game":"紙牌","medium":"顯影明膠銀鹽照片","size":"7.5×10.0公分","credit":"","p":["這是貼在某本相簿裡的小照片，美術館的標題是「打牌的人們」。拍攝者和地點都不清楚。","在天花板垂下的油燈光下，穿條紋衣服的女子、女孩和男孩們圍著鋪流蘇桌布的桌子，把手牌像扇子一樣展開。在暗室裡拍照應該很難，這應是想留下家人夜晚團聚的一張照片。"],"spots":[["流蘇桌布","有花紋和流蘇的桌布。"],["油燈","從天花板垂下的油燈。"],["條紋衣服的女子","穿白條紋衣服坐著的女子。"],["女子的手牌","女子像扇子一樣拿著的牌。"],["女孩的手牌","中間的女孩展開的牌。"],["右邊的男孩","探身拿著牌的男孩。"]]},"borduur":{"title":"刺繡牌局的牌桌桌面","artist":"佚名","date":"1700—1725年","place":"不詳","game":"紙牌","medium":"彩色毛線和絲線的粗針繡與細針繡","size":"100×185公分","credit":"","p":["這是一張摺疊式牌桌桌面上的刺繡，用多色毛線和絲線，分用粗針的大十字繡和細針的小十字繡。在切去四角的形狀裡，圍著一圈渦卷和花朵的飾框。","中央的風景裡，兩位夫人和一位紳士圍著桌子打牌。據美術館記錄，桌上放著錢袋、紙牌和其他遊戲用具。在打牌用的桌子上繡上打牌的場面，十分別緻。"],"spots":[["桌面","放著錢袋和紙牌的綠色桌子。"],["紳士","坐在左邊戴帽子的男子。"],["中間的夫人","坐在桌子後面的夫人。"],["右邊的夫人","穿藍衣坐著的夫人。"],["樹木","人物身後茂密的樹。"],["飾框","渦卷和花朵的邊框。"]]},"piquet":{"title":"印有皮克牌的布","artist":"佚名","date":"1725—1750年","place":"不詳","game":"皮克牌（紙牌遊戲）","medium":"亞麻布，紅紫兩色印花","size":"73.0×82.5公分","credit":"","p":["這是一塊鋪在牌桌上的亞麻布，滿滿印著紅紫兩色的紙牌遊戲用具。美術館記錄也把它稱作手帕。","邊框和中央散佈著皮克牌（用7到A共32張牌玩的遊戲）的牌，中間畫著錢袋，四周是籌碼。國王、王后、傑克的人頭牌是帶有凱撒、阿爾金、奧吉耶等名字的「巴黎式」。"],"spots":[["錢袋","中央畫的賭注錢袋。"],["人頭牌","巴黎式的國王和王后牌。"],["籌碼","圓形籌碼。"],["紙牌邊框","布四周排滿紙牌的邊。"],["背面朝上的牌疊","露出背面花紋的牌疊。"],["封好的牌包","右下封好的牌包。"]]},"schaakglas":{"title":"刻有兩人下西洋棋的高腳杯","artist":"佚名","date":"1815—1830年","place":"不詳","game":"西洋棋","medium":"無色透明玻璃，輪刻","size":"高13.7公分","credit":"","p":["這是一隻帶腳的透明玻璃杯，用旋轉的小砂輪刻出圖畫和文字。在立著兩支蠟燭的小桌旁，兩個男人隔著棋盤相對。","左邊的人戴眼鏡、叼著菸斗，右邊的人俯身看棋盤，桌上還放著酒杯。四周刻著法語：「懂走法很簡單，懂棋局是天賦的果實。」"],"spots":[["棋盤","擺著棋子的棋盤。"],["叼菸斗的人","左邊戴眼鏡、叼菸斗的人。"],["俯身的人","右邊湊近看棋的人。"],["蠟燭","棋盤那邊的兩支蠟燭。"],["酒杯","桌上的杯子。"],["銘文","用法語刻的文字。"]]},"arlequin":{"title":"阿勒坎的樂透遊戲","artist":"佚名（明德曼公司出版）","date":"1818—1845年","place":"荷蘭（阿姆斯特丹）","game":"樂透／賽跑遊戲","medium":"雕版，手工上色，裱於厚紙板","size":"不詳","credit":"","p":["這是一張把叉腿站立的阿勒坎（丑角）本身做成棋盤的遊戲版畫。綠衣的身體和兩腿之間，排著1到32號的方格。下方有「Arlequin’s Lotto-Spel」的標題和阿姆斯特丹明德曼公司的名字。","他臉上戴著網面罩，手裡拿著帽子和像木劍的東西。有些格子標著「HW」或「P」。這張手工上色的版畫裱在厚紙板上，應是當作棋盤用的。"],"spots":[["網面罩","遮住臉的網罩。"],["1號格","左腿下的起點格。"],["HW格","標著「HW」的格子。"],["P32","標著「P」的32號格。"],["標題","下方的「Arlequin’s Lotto-Spel」。"],["帽子","右手拿的帽子。"]]},"vicaire":{"title":"副本堂神父的一局牌","artist":"勒內·加揚（據圖版標注）","date":"1888—1893年","place":"法國","game":"紙牌","medium":"珂羅版（據美術館記錄）","size":"10.4×15.6公分","credit":"","p":["這是刊登在《巴黎攝影俱樂部會刊》上的圖版，題為「La partie du Vicaire（副本堂神父的一局牌）」。下方邊上印著「Phototype René Gayant」「Héliogravure Lemercier」，應是加揚拍攝、勒梅西耶公司印製。書中是橫著裝訂的。","掛著鍋和平底鍋的廚房裡，穿黑色神父袍的神父坐在桌邊盯著牌，對面的男人也拿著牌。戴帽子的男人托著腮，年輕人用手貼著耳朵看牌局。像繪畫一樣的光線和構圖，很符合追求藝術攝影的攝影俱樂部。"],"spots":[["神父的手牌","神父在手邊盯著的牌。"],["神父","穿黑袍、戴白領的神父。"],["拿牌的男人","捲髮男人，低頭看牌。"],["看牌的年輕人","手貼著臉頰看牌局的年輕人。"],["戴帽子的男人","托著腮的戴帽男人。"],["廚房牆","掛著鍋和勺子的牆。"]]},"israels":{"title":"下西洋棋的人們","artist":"伊薩克·伊斯拉埃爾斯","date":"1875—1922年","place":"荷蘭","game":"西洋棋","medium":"粉彩畫","size":"40.0×57.5公分","credit":"","p":["這是以快速生動的筆觸描繪阿姆斯特丹城市生活的荷蘭畫家伊薩克·伊斯拉埃爾斯（1865—1934年）的粉彩畫。窗戶明亮的房間裡，男人們圍著棋盤。","前面兩人一個手托臉頰、一個手托下巴，緊盯棋盤；後面一個戴帽子的男人探身來看。棋子沒有細畫，只用色點表示，彷彿長長的思考時間正在流逝。"],"spots":[["棋盤與棋子","桌上的棋盤，棋子用色點畫成。"],["左邊的棋手","手托臉頰看棋的人。"],["右邊的棋手","手托下巴思考的人。"],["戴帽子的人","從後面探身來看的人。"],["窗戶","左邊明亮的窗戶。"],["椅子","右前方的椅子。"]]},"louisxi":{"title":"路易十一與女兒安娜·德·博熱","artist":"阿德里安·約瑟夫·費爾霍芬-巴爾","date":"1866年","place":"比利時（安特衛普）","game":"西洋棋","medium":"版畫（應為蝕刻）","size":"26.4×31.3公分","credit":"","p":["這是安特衛普畫家費爾霍芬-巴爾自己畫、自己刻的版畫（下方有「pinx et sculp（繪並刻）」）。美術館的標題是「路易十一與女兒安娜·德·博熱下西洋棋」。下方還寫著「安特衛普藝術家協會第二屆展覽」。","15世紀的法國國王路易十一穿著毛皮長袍坐在桌前，女兒安娜手托下巴看著棋盤。桌上有棋子和果盤，地上臥著一隻狗，後面還站著手持兵器的衛兵。這應是想像中的歷史父女場面。"],"spots":[["棋盤與棋子","桌上的棋盤和棋子。"],["路易十一","戴帽子、穿毛皮長袍的國王。"],["安娜","手托下巴看棋的女兒。"],["臥著的狗","臥在地上的細長的狗。"],["後面的衛兵","暗處持兵器的衛兵。"],["標題","「LOUIS XI ET SA FILLE ANNE DE BEAU-JEU」。"]]},"bruining":{"title":"下跳棋的修士們","artist":"蒂勒曼·卡托·布賴寧","date":"1750—1850年","place":"荷蘭","game":"跳棋","medium":"蝕刻版畫","size":"20.6×16.8公分","credit":"","p":["這是荷蘭版畫家布賴寧的蝕刻版畫，左下寫著「T. Bruining inv. et fecit aqua fort（設計並蝕刻）」。據美術館說，兩位修士坐在桌旁下跳棋。","他們身後站著第三位修士和一個穿修士袍的魔鬼。桌邊還站著同樣扮成修士的「死神」，把大鐮刀藏在背後。修士們沉迷於棋局，沒有察覺悄悄進來的不速之客。"],"spots":[["跳棋棋盤","桌上的棋盤和棋子。"],["死神","穿修士袍、把大鐮刀藏在背後的死神。"],["後面的兩個","第三位修士和穿修士袍的魔鬼。"],["左邊的棋手","俯身在棋盤上的修士。"],["右邊的棋手","手臂搭在桌上思考的修士。"],["簽名","「T. Bruining inv. et fecit aqua fort」。"]]},"vanvliet":{"title":"燭光下的特里克特拉克","artist":"揚·希利斯·范弗利特","date":"1631—1634年","place":"荷蘭（萊頓）","game":"特里克特拉克（雙陸的一種）","medium":"蝕刻與雕版","size":"15.2×13.4公分","credit":"","p":["這是與林布蘭同在萊頓工作的版畫家范弗利特的作品。據美術館說，在左邊有華蓋床的昏暗房間裡，兩人在玩特里克特拉克，右邊有一男一女。","穿黑衣的男人背對我們深深俯身看棋盤，對面的人笑著把手搭在棋盤邊上。棋盤上的三角格和棋子清晰可見。看不到光源，只有棋盤和人臉被照亮，應是夜裡的一局。"],"spots":[["棋盤","能看到三角格和棋子的特里克特拉克棋盤。"],["笑著的棋手","手搭棋盤邊、笑著的人。"],["俯身的人","背對我們、俯身看棋的黑衣男人。"],["戴帽子的人","站在後面、戴寬簷帽的男人。"],["戴褶領的人","右邊舉手的戴褶領的人。"],["床帳","左邊華蓋床的簾子。"]]},"hermans":{"title":"圍著棋盤的兩位女子和小女孩","artist":"弗朗索瓦·赫爾曼斯（照相館）","date":"1857—1895年","place":"荷蘭（鹿特丹）","game":"西洋棋","medium":"蛋白照片（名片照）","size":"10.1×6.2公分","credit":"","p":["這張名片照貼在家庭相簿裡，背面印著照相館名「François Hermans / Hang 421 / Rotterdam」。應是在照相館拍的家庭紀念照。","小圓桌上放著西洋棋盤，左邊的女子手搭在棋子上，右邊的女子托腮思考。兩人之間站著的小女孩正直直地看著我們。在長時間曝光中，三人大概都一動不動。"],"spots":[["棋盤","圓桌上的棋盤和棋子。"],["移動棋子的手","左邊女子把手搭在棋子上。"],["小女孩","站在棋盤後面看著我們的小女孩。"],["思考的女子","托腮的右邊女子。"],["腳凳","地上的圓腳凳。"],["窗戶","右後方的格子窗。"]]},"norimberg":{"title":"刻有紐倫堡城景的跳棋子","artist":"佚名","date":"1690年","place":"德國（紐倫堡）","game":"跳棋或雙陸","medium":"黃楊木","size":"直徑5.4公分，厚1.5公分","credit":"","p":["這是一枚黃楊木跳棋子，浮雕著塔樓和城堡林立的紐倫堡城景。上方刻著「SVB AQVILAE ROMANAE ALIS QVIESCO（我棲息於羅馬之鷹的翼下）」，下方刻著「NORIBERGA VRBIVM REGINA（城市之后紐倫堡）」。","據美術館記錄，另一面刻有皇帝約瑟夫一世和七位選帝侯的肖像。應是把神聖羅馬帝國的帝國城市紐倫堡的自豪刻進了遊戲用具。"],"spots":[["城景","教堂尖塔和城牆林立的紐倫堡。"],["上方銘文","「SVB AQVILAE ROMANAE…」字樣。"],["下方銘文","「NORIBERGA VRBIVM REGINA」字樣。"],["紋飾","最上方的小紋飾。"],["城堡","右邊高處的城堡。"],["邊緣","棋子邊上的台階。"]]},"toovenaar":{"title":"賽跑遊戲《魔法師》","artist":"佚名","date":"1856年","place":"荷蘭（阿姆斯特丹）","game":"賽跑遊戲（鵝棋的一種）","medium":"石版畫，活字印刷文字，手工上色","size":"44.5×53.5公分","credit":"","p":["這是一張題為「DE TOOVENAAR（魔法師）／新穎有趣的兒童遊戲」、1到63格螺旋排列的賽跑遊戲。中央畫著站在擺有骷髏、聖杯、月亮和星星的桌前的魔法師，身後有惡魔般的生物；四角也有獸頭惡魔。","印在中央的規則和鵝棋差不多：擲兩枚骰子，第一次擲出6和3就到26，5和4就到53。落到魔法師格要像鵝格那樣再走一次；過橋付一，進酒館付二並停一回，到42號迷宮退三格，碰到死神要付錢並從頭開始。"],"spots":[["魔法師","中央桌前的魔法師。"],["標題與規則","「DE TOOVENAAR」的標題和玩法。"],["終點63","螺旋最後一格。"],["角上的惡魔","四角的獸頭惡魔。"],["外圈的格子","帶圖的格子沿外圈排列。"],["桌上的器物","擺著骷髏和聖杯的桌子。"]]},"fichesdoos":{"title":"象牙籌碼盒","artist":"小馬里亞瓦爾","date":"1725年","place":"法國（巴黎）","game":"紙牌遊戲的籌碼","medium":"象牙","size":"2×8×6公分","credit":"","p":["這是一個巴掌大的象牙盒，裝著紙牌遊戲中代替錢的籌碼。盒蓋上畫著坐在雲上、戴冠持杖的女子和孔雀，以及兩枚紋章。帶著孔雀的女子應是女神朱諾。","據美術館記錄，蓋上寫著「Mariaval le Jeune a Rouen fecit（盧昂的小馬里亞瓦爾製）」，底面畫著鷹和群鳥，其中一隻吊在絞架上。盒裡還留著畫有昆蟲和花的大籌碼19枚、小籌碼6枚。"],"spots":[["戴冠的女子","坐在雲上戴冠的女子。"],["孔雀","女子腳邊的孔雀。"],["紋章","右上並排的兩枚紋章。"],["小鳥","女子身旁棲木上的鳥。"],["雲","托著女子的雲。"],["蓋緣","盒蓋的邊緣和扣件。"]]},"vuilmere":{"title":"下跳棋的畫家母親","artist":"愛德華·維亞爾","date":"約1890—91年","place":"法國","game":"跳棋（國際跳棋）","medium":"粉彩、鉛筆，擦筆與擦拭·象牙色紙","size":"37.5×30.5公分","credit":"","p":["這是法國畫家維亞爾畫母親的粉彩畫。維亞爾和母親同住，一次又一次地畫當裁縫的母親家中的場景。右下角有「E Vuillard」的簽名。","兩位穿黑衣的人隔著鮮豔的橙色桌子坐著，前面的人手裡拿著跳棋盤。據美術館的標題，畫中是畫家的母親。在橢圓形的黑線裡，人和家具融成一塊塊色彩與形狀。"],"spots":[["棋盤","黑白相間的棋盤。"],["後面的人","坐在桌子那邊的黑衣人。"],["前面的人","拿著棋盤的人。"],["橙色桌子","鋪滿畫面的鮮豔顏色。"],["花紋牆","用捲曲線條畫的牆面花紋。"],["簽名","右下的「E Vuillard」。"]]},"dewitte":{"title":"下西洋棋的兩個男人","artist":"阿德里安·德維特","date":"1877年","place":"比利時","game":"西洋棋","medium":"應為蝕刻","size":"13.2×12.5公分","credit":"","p":["這是比利時列日的畫家、版畫家德維特（1850—1935年）的一幅小版畫。據美術館說，研究文獻（克萊克斯，1981年）認為下棋的兩人是特爾姆和澤延。","鋪著桌布的桌旁，年輕人抱著胳膊俯視棋盤，對面年長的人手扶著頭沉思。棋盤後面還能看到像是棋子盒的東西。細線層層疊加的昏暗房間裡，一局棋靜靜進行。"],"spots":[["棋盤與棋子","桌上的棋盤和棋子。"],["棋子盒","棋盤後面像是盒子的東西。"],["年輕人","抱著胳膊俯視棋盤的人。"],["年長的人","手扶著頭思考的人。"],["桌布","鋪在桌上的布。"],["椅子","左邊曲木椅的椅背。"]]},"orphans":{"title":"孤兒們（下跳棋的孩子）","artist":"查爾斯·羅爾斯（據W. 吉爾原畫）","date":"1810—1834年","place":"英國","game":"跳棋","medium":"版畫（雕版）","size":"22.6×13.9公分","credit":"","p":["這是一幅下方題為「THE ORPHANS（孤兒們）」的版畫，寫著「W. 吉爾畫，C. 羅爾斯刻」。據美術館說，它可能用於倫敦出版的年刊禮品書《紀念冊》（The Keepsake）。","廚房裡，一個女孩和一個男孩把棋盤放在木桶上下跳棋。後面一位婦女在刺繡，裡面還有美術館稱為織布機的器具。從標題看，兩個孩子應是被這位婦女收養的孤兒。"],"spots":[["跳棋棋盤","放在木桶上的棋盤和棋子。"],["女孩","探身看棋盤的女孩。"],["男孩","移動棋子的男孩。"],["刺繡的婦女","後面做針線的婦女。"],["水罐","放在地上的水罐。"],["標題","下方的「THE ORPHANS」。"]]},"richelieu":{"title":"路易十三與黎塞留","artist":"揚·弗雷德里克·克里斯蒂安·雷克勒本","date":"1850年","place":"荷蘭（阿姆斯特丹）","game":"西洋棋","medium":"鋼版畫","size":"24.2×29.6公分","credit":"","p":["這是阿姆斯特丹版畫家雷克勒本的鋼版畫，上方寫著「1850. NEDERLANDSCH MUSEUM. Pl. II.」。據美術館說，它可能是雜誌《荷蘭博物館》一篇文章的插圖。","在大壁爐前，法國國王路易十三和宰相黎塞留樞機主教在下西洋棋，周圍聚著一群男人。坐在左邊的樞機主教伸手拿棋子，戴羽毛帽的國王從容地坐著。最左邊站著一位抱臂的修士。"],"spots":[["棋盤","鋪布的桌上的棋盤和棋子。"],["黎塞留","伸手拿棋子的樞機主教。"],["路易十三","戴羽毛帽的國王。"],["修士","在最左邊抱臂觀看的修士。"],["圍觀的廷臣","聚在右邊的男人們。"],["標題","下方的「LODEWIJK DE XIII EN RICHELIEU」。"]]},"coster":{"title":"燭光下玩特里克特拉克的人們（據德科斯特）","artist":"據亞當·德科斯特油畫（福斯特曼刻）","date":"1619—1628年","place":"法蘭德斯","game":"特里克特拉克（雙陸的一種）","medium":"雕版畫","size":"37.1×35.1公分","credit":"","p":["這是據以燭光畫著稱的法蘭德斯畫家亞當·德科斯特的油畫製作的版畫，下方有「A. De Coster pi.」和「Vorsterman」字樣。據美術館說，兩個男人站在桌前藉著燭光玩特里克特拉克。","左邊一個叼菸斗的男人在旁觀看，右邊一個少女彈著魯特琴，一個戴帽子的男人指著蠟燭。前面的人背對我們俯身在桌上，對面的人把手懸在棋盤上方。只有一支蠟燭照亮場面，只映出臉和手。"],"spots":[["棋盤","桌上半隱在暗處的棋盤。"],["蠟燭","照亮全場的一支蠟燭。"],["背對的棋手","俯身在桌上的棋手。"],["對面的棋手","把手懸在棋盤上方的人。"],["抽菸斗的人","在左邊抽著菸斗觀看的人。"],["彈魯特琴的少女","右邊彈魯特琴的少女。"]]},"kiebitz":{"title":"旁觀者（看牌的人）","artist":"漢斯·瓦采克","date":"1894年","place":"應為奧地利","game":"紙牌","medium":"網版印刷（書中插圖）","size":"10.0×12.1公分","credit":"","p":["這是維也納藝術攝影家漢斯·瓦采克的照片，右上角簽有「HANS WATZEK 94」。它以網版印在一本頁眉寫著「攝影是藝術嗎？」的書裡。","德語標題「Kiebitz」原指鳳頭麥雞，也是俗語，指在牌局旁插嘴的看客。戴帽子的男人盯著手牌，前面叼長菸斗的男人從旁邊探看。粗粒的、像繪畫一樣的調子，是當時追求接近繪畫的藝術攝影的特色。"],"spots":[["手牌","右邊男人盯著的牌。"],["拿牌的男人","戴圓頂禮帽、叼著菸斗的男人。"],["看客","叼長菸斗的男人，應是標題裡的「Kiebitz」。"],["啤酒杯","桌上的玻璃啤酒杯。"],["簽名","右上的「HANS WATZEK 94」。"],["標題","下方的「HANS WATZEK. — KIEBITZ.」。"]]},"evdvelde":{"title":"城堡花園裡玩特里克特拉克的人們","artist":"埃薩亞斯·范德費爾德","date":"1630年","place":"荷蘭","game":"特里克特拉克（雙陸的一種）","medium":"黑粉筆、灰色淡彩","size":"18.5×30.1公分","credit":"","p":["這是荷蘭風俗畫和風景畫的先驅之一埃薩亞斯·范德費爾德（1587—1630年）的素描，右下簽著「E.V.VELDE」。據美術館說，衣著華麗的人們在城堡花園裡圍著桌子玩特里克特拉克。","一個站著俯身的男人和一個坐著的男人隔著棋盤，後面有女士們觀看。左前方是冰酒器和兩隻酒壺，再往裡是噴泉邊的少年和孔雀。這是在戶外遊戲的優雅午後。"],"spots":[["棋盤","桌上的特里克特拉克棋盤。"],["俯身的男人","戴帽子、俯身向棋盤的男人。"],["坐著的男人","翹著腿對著棋盤的男人。"],["觀看的女士","站在後面看棋的女士。"],["孔雀與少年","噴泉邊的孔雀和少年。"],["冰酒器","左前方的器皿和兩隻酒壺。"]]},"cooghen":{"title":"玩特里克特拉克的兩個男人","artist":"萊恩德特·范德庫亨","date":"1666年","place":"荷蘭（哈勒姆）","game":"特里克特拉克（雙陸的一種）","medium":"蝕刻版畫","size":"9.3×15.6公分","credit":"","p":["這是哈勒姆畫家范德庫亨的蝕刻版畫，棋盤上方的牆上刻著「1666」年份。據美術館說，酒館裡兩個男人在桌邊玩特里克特拉克，一位女子從左邊男人的肩後探看。","左邊年長的男人穿毛皮鑲邊外衣，手拿高腳杯；右邊年輕男人戴著顯眼的羽飾帽子。窗邊坐著一隻小猴子。棋盤的邊框和三角格刻得很清楚。"],"spots":[["棋盤","桌上的特里克特拉克棋盤。"],["年長的男人","穿毛皮鑲邊外衣的男人。"],["酒杯","年長男人手裡的高腳杯。"],["探看的女子","從左邊男人肩後探看的女子。"],["窗邊的猴子","坐在窗邊的小猴子。"],["羽飾帽的人","戴羽飾帽子的年輕人。"]]},"roybet":{"title":"下棋的人","artist":"費迪南·魯瓦貝","date":"1875年","place":"法國（巴黎）","game":"西洋棋","medium":"應為蝕刻","size":"26.1×19.6公分","credit":"","p":["這是喜歡畫17世紀騎士的法國畫家魯瓦貝自己畫、自己刻的版畫（左下有「F. Roybet del. et sc.」）。下方寫著「LE JOUEUR D’ÉCHECS（下棋的人）」，右下有出版商卡達爾的名字。","戴羽毛帽、佩著劍的男人側身坐在長凳上，伸手去拿棋子。看不到對手，他似乎在獨自思考棋局。後面的架子上擺著啤酒杯、水壺和玻璃杯。"],"spots":[["棋盤與棋子","長凳上的棋盤和棋子。"],["騎士","戴羽毛帽的男人。"],["伸向棋子的手","伸手拿棋子的男人。"],["劍","腰間的長劍。"],["架上的器皿","啤酒杯、水壺和玻璃杯。"],["標題","「LE JOUEUR D’ÉCHECS」字樣。"]]},"capot":{"title":"「聖彼得，朋友，你被『卡波』了！」（畫家與模特打牌）","artist":"佚名（奧貝爾公司出版）","date":"1838年","place":"法國（巴黎）","game":"紙牌（應為皮克牌）","medium":"石版畫","size":"30.5×22.2公分","credit":"","p":["這是刊登在巴黎諷刺報《喧鬧報》1838年9月9日號上的石版畫，上方標著「Les Artistes（藝術家們）」第13號。下方的台詞是「聖彼得，朋友，你被『卡波』了！」","據美術館說，畫家把牌友叫作「聖彼得」，因為這個人正是身後畫中聖人的模特。「卡波」指在皮克牌中一墩也沒拿到而大敗，所以他們玩的應是皮克牌。"],"spots":[["桌上的牌","小桌上打出的牌。"],["模特","背對我們的長髮男人，頭髮和鬍子與畫中聖人相同，應是模特。"],["畫家","右邊拿著手牌的男人，應是畫家。"],["聖人畫","畫架上畫了一半的聖人。"],["凳子","模特坐的木凳。"],["台詞","「St. Pierre, mon ami, vous êtes capot!」。"]]},"ziacard":{"title":"梅花K（齊亞普韋布洛總督安東尼奧·薩爾瓦）","artist":"亞當·克拉克·弗羅曼（攝影）、拉扎勒斯與梅爾策（出版）","date":"1900年","place":"美國（洛杉磯）","game":"撲克牌","medium":"網目版照相印刷","size":"8.8×6.3公分","credit":"","p":["據美術館紀錄，這是一盒53張（含鬼牌）撲克牌中的一張，牌面用網目版印著美洲原住民的照片。照片由亞當·克拉克·弗羅曼拍攝，洛杉磯的拉扎勒斯與梅爾策出版。","梅花K上沒有畫國王，而是新墨西哥州齊亞普韋布洛總督安東尼奧·薩爾瓦的肖像。下方印著他的名字和頭銜，角上有K和梅花標記。這副牌可能是為前往美國西部的遊客製作的紀念品。"],"spots":[["角標","左上角的K和梅花，與一般撲克相同。"],["總督的臉","側臉望向一旁的安東尼奧·薩爾瓦。"],["長髮","齊肩的長髮和剪齊的瀏海。"],["領口的布","白襯衫領口繫著的布巾。"],["名字和頭銜","印著「安東尼奧·薩爾瓦，齊亞普韋布洛總督」。"],["倒置的角標","右下角倒著的K和梅花。"]]},"gothink":{"title":"下圍棋的兩位女子和一位男子","artist":"日本攝影師（佚名）","date":"1887—1897年","place":"日本","game":"圍棋","medium":"手工上色照片（書中插圖）","size":"8.8×13公分","credit":"","p":["這張照片由一位佚名的日本攝影師拍攝，並在日本手工上色，貼在一本介紹日本的英文書第65頁作插圖。下方印的英文說明：「圍棋是比西洋棋更難的遊戲，8世紀從中國傳入日本。」","榻榻米上隔著有腳的棋盤，左邊的女子落子，白鬍子老人手按頭部陷入沉思。中間的女子注視棋盤，前面擺著點心盤和茶碗。這可能是為外國遊客在照相館裡擺拍的。"],"spots":[["棋盤","有腳的棋盤上擺著棋子。"],["落子的手","左邊女子把手伸向棋盤。"],["沉思的老人","白鬍子老人手按著頭。"],["觀棋的女子","中間穿條紋和服、注視棋盤的女子。"],["點心盤","前面盤子裡的點心。"],["棋罐","棋盤旁帶蓋的棋子罐。"]]},"craps":{"title":"少年賭徒","artist":"弗朗西斯·A·普萊斯","date":"1888—1893年","place":"可能是美國","game":"骰子","medium":"照片（書中插圖）","size":"14×9.9公分","credit":"","p":["據美術館紀錄，照片拍的是四個身分不明的男孩玩骰子，襯紙上印著攝影師弗朗西斯·A·普萊斯的名字。它貼在一本書第142頁之前兩頁，印有「印在美國『Aristo』相紙上」「用威廉斯閃光燈裝置拍攝」。它可能兼作相紙和閃光燈的樣張。","鋪著稻草的牆邊，男孩們圍著一隻木箱。箱上有一個鐵皮碟和兩顆骰子。右邊的男孩打著響指，坐在地上的男孩手托下巴盯著看。下方地面刻著「COME SEV」，可能是美國骰子賭博「花旗骰」裡喊「來個七！」的口號。"],"spots":[["兩顆骰子","木箱上的兩顆骰子。"],["鐵皮碟","箱上的碟子，可能用來放賭注。"],["打響指的男孩","右邊男孩對著骰子打響指。"],["坐著的男孩","坐在地上、手托下巴的男孩。"],["「COME SEV」","下方刻的字，可能是「來個七！」。"],["木箱上的字","箱側印著的字母。"]]},"bikkel":{"title":"玩抓羊拐的男子習作","artist":"揚·巴普蒂斯特·韋尼克斯（推測）","date":"1642—1647年","place":"義大利（羅馬）","game":"抓羊拐（擲骨遊戲）","medium":"黑白粉筆，藍紙","size":"26.7×18.0公分","credit":"","p":["這是在藍紙上用黑白粉筆畫的素描。據美術館說，可能是荷蘭畫家韋尼克斯在羅馬時期所作；以前曾作為帕拉梅德斯的作品出售。","戴帽子的男人深深彎下腰，盯著手裡；腳邊地上散著幾塊小骨頭。拋接羊等動物的踝骨是一種古老的遊戲，常被說成是骰子的祖先。"],"spots":[["臉","從帽簷下看著手裡。"],["手","應是正要拋骨頭的手。"],["地上的骨頭","地上散落的小骨頭。"],["鞋","用力踩地的腳。"],["白粉筆","表現光線的白色粉筆。"],["斗篷","背上展開的斗篷。"]]},"stukken":{"title":"西洋棋棋子設計圖","artist":"佚名（法國）","date":"1850—1875年","place":"法國","game":"西洋棋","medium":"鋼筆黑墨水，白色與朱紅不透明顏料，黑粉筆底稿，藍紙","size":"26.5×20.0公分","credit":"","p":["這是一套西洋棋棋子的設計圖，作者不詳，畫於法國。上下兩排各有國王、皇后、城堡、人物棋子和騎士五種。","上排是戴冠的國王和皇后、跪著持槍的士兵；下排是纏頭巾的國王、戴面紗的皇后和跪著拉弓的士兵，兩方應是被設計成西方和東方的軍隊。白色和朱紅顏料表現了雕刻與光澤。"],"spots":[["國王（上）","戴冠、持權杖的國王。"],["皇后（上）","戴冠的皇后。"],["塔","作為城堡的塔。"],["持槍士兵","跪著持槍的棋子。"],["頭巾國王","下排的國王。"],["弓箭手","下排拉弓的棋子。"]]},"rozetempel":{"title":"花園，或歡樂的玫瑰神殿（骰子遊戲盤）","artist":"佚名（亨德里克·莫勒奈澤爾出版）","date":"1792—1847年","place":"荷蘭（阿姆斯特丹）","game":"骰子遊戲盤","medium":"版畫","size":"46.1×39.6公分","credit":"","p":["這是阿姆斯特丹出版商莫勒奈澤爾發行的單張遊戲盤，上方標題是「BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL（花園，或歡樂的玫瑰神殿）」。","中央的「ROZE TEMPEL」裡有一瓶玫瑰，周圍一圈排著兩顆骰子的點數組合和花。玩法應是擲兩顆骰子，在對應的花那裡付出或收取賭注。"],"spots":[["標題","「BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL」。"],["玫瑰神殿","中央的「ROZE TEMPEL」。"],["骰子點數","兩顆骰子的點數組合。"],["玫瑰花瓶","神殿裡的一瓶玫瑰。"],["鬱金香","周圍的花之一。"],["出版商","「Te AMSTERDAM bij H. Moolenyzer」。"]]},"brelan":{"title":"布雷朗（選自《童戲》）","artist":"克洛迪娜·斯特拉（據雅克·斯特拉原畫）","date":"1657年","place":"法國（巴黎）","game":"布雷朗（三張牌的紙牌遊戲）","medium":"雕版畫","size":"12.0×14.2公分","credit":"","p":["這是收錄51個兒童遊戲場面的畫冊《童年的遊戲與樂趣》中的一頁。詩句上方寫著「LE BRELAN」，胖嘟嘟的孩子們坐在地上打牌。","詩裡說：一個孩子滾著鐵環，其他孩子擠在一起用紙牌碰運氣，以為穩贏的那個反倒輸了錢。布雷朗常被說成是撲克的遠祖之一。"],"spots":[["手牌","展開手牌看的孩子。"],["地上的牌","地上一張標著「A」的牌。"],["偷看的孩子","從後面偷看手牌的孩子。"],["滾鐵環","用棍子滾鐵環的孩子。"],["塔","背景中的圓塔。"],["標題","「LE BRELAN」和詩句。"]]},"pwkarte":{"title":"六隻鸚鵡的圓形紙牌","artist":"科隆的PW大師","date":"1470—1500年","place":"德國（科隆）","game":"紙牌（圓形牌）","medium":"雕版畫","size":"直徑7.0公分","credit":"","p":["這是五百多年前用雕版印出的一張圓形紙牌。據美術館說，它屬於一副70張的圓牌，分為玫瑰、耬斗菜、康乃馨、鸚鵡和野兔五種花色。","每種花色有標1到10的數字牌10張，還有畫人物的人頭牌4張。這張是「鸚鵡6」，上方是阿拉伯數字「6」，下方是羅馬數字「VI」，六隻鸚鵡圍著中央的裝飾。"],"spots":[["「6」","上方的阿拉伯數字。"],["「VI」","下方的羅馬數字。"],["上面的鸚鵡","像是停在枝上的鸚鵡。"],["展翅的鸚鵡","張開翅膀的鸚鵡。"],["倒掛的鸚鵡","頭朝下的鸚鵡。"],["中央的裝飾","放出光芒的中央裝飾。"]]},"nilson":{"title":"棋盤遊戲（跳棋與托卡迪耶）","artist":"約翰·埃薩亞斯·尼爾松","date":"1731—1788年","place":"德國（奧格斯堡）","game":"跳棋（國際跳棋）與托卡迪耶","medium":"蝕刻與雕版","size":"18.9×28.8公分","credit":"","p":["這是奧格斯堡版畫家尼爾松設計並出版的洛可可飾框版畫，上方寫著「Das Bretspiel（棋盤遊戲）」，是四張一組中的第三張。","據美術館說，左邊桌上一男一女在下跳棋，右邊桌上兩個男人在玩托卡迪耶——一種雙陸類遊戲。下方德文詩句的意思是：玩托卡迪耶的人一心想贏，下跳棋的人要用盡全部心思。"],"spots":[["跳棋盤","左邊桌上的跳棋盤。"],["托卡迪耶盤","右邊小桌上的棋盤。"],["讀信的男人","叼著菸斗讀信的男人。"],["端器皿的女子","右邊端著餐具的女子。"],["園景","飾框後面的公園。"],["詩句","「Wer Tocadille spielt…」。"]]},"chateau":{"title":"紙牌城堡","artist":"弗朗索瓦·茹蘭（據夏爾-安托萬·夸佩爾原畫）","date":"1725年","place":"法國（巴黎）","game":"紙牌（搭紙牌屋）","medium":"雕版畫","size":"23.2×15.8公分","credit":"","p":["這是茹蘭根據畫家夸佩爾的原畫刻製、由巴黎的迪尚日出版的版畫。地上的一張紙上寫著「CH. COYPEL」。","打扮華麗的孩子在桌上用紙牌搭城堡，後面的少年把手指放在嘴邊看著。下方詩句嘲諷賭牌：笑這些孩子搭起一吹就倒的城堡的人，若從沒把紙牌用在別處，倒也算個聰明人。"],"spots":[["紙牌城堡","桌上搭起的紙牌。"],["手中的牌","孩子手裡拿的牌。"],["搭城堡的孩子","戴羽飾帽的孩子。"],["觀看的少年","把手指放在嘴邊的少年。"],["地上的紙","寫著「CH. COYPEL」的紙。"],["詩句","「Tel qui rit, voyant ces Enfans…」。"]]},"pugillus":{"title":"輸光骰子的青年與盛裝女子","artist":"雅各布·范德海登（推測）","date":"1608—1618年","place":"法國（斯特拉斯堡）","game":"骰子","medium":"雕版畫","size":"9.0×13.2公分","credit":"","p":["這是面向學生的漫畫版畫集《Pugillus facetiarum iconographicarum》（一把圖畫笑話）中的一張，據美術館說原本大概有36張以上。","左邊是拿著扇子的盛裝女子，右邊是衣衫破爛的青年舉起帽子，看著地上的兩顆骰子和空錢袋。下方的話大意是「眼睛的天堂、心靈的地獄、錢袋的煉獄」和「從來沒有現錢，褲子總是破的」，嘲笑沉迷女色和賭博。"],"spots":[["盛裝女子","戴皮帽、穿長袍。"],["扇子","女子手裡的羽毛扇。"],["舉帽的青年","像打招呼一樣舉起帽子。"],["破衣服","破爛的上衣和褲子。"],["骰子與錢袋","地上的兩顆骰子和空錢袋。"],["題詞","「Nunquam bar gelt, semper zerrissen hosen」。"]]},"grootebroek":{"title":"赫羅特布魯克的彩券","artist":"科內利斯·迪薩特","date":"1694—1695年","place":"荷蘭（哈勒姆／阿姆斯特丹）","game":"彩券","medium":"美柔汀與雕版","size":"25.1×19.5公分","credit":"","p":["1694年8月20日，恩克赫伊森附近的赫羅特布魯克村發生大火，人們為受災者舉辦了彩券。這是迪薩特的版畫，由阿姆斯特丹的霍勒出版。","據美術館說，一個男人把水壺和封好的信送到中獎者家。下方標題的意思是「看那豐厚獎品被歡天喜地地送回家」。吹號的男人、舉起水壺的男人和在窗口舉起雙手的女人，傳達了中獎的熱鬧。"],"spots":[["封好的信","送給中獎者的信。"],["水壺","舉起獎品水壺的男人。"],["號角","吹號報喜的男人。"],["窗口的女人","驚喜地舉起雙手。"],["狂歡的人們","右邊喝酒慶祝的人。"],["標題","「Lottery van Groottenbroek」。"]]},"narren":{"title":"擲骰子的兩個弄臣（伊拉斯謨《愚人頌》插圖）","artist":"卡斯帕·梅里安（據漢斯·霍爾拜因與安布羅修斯·霍爾拜因素描）","date":"1516年（素描）","place":"瑞士（巴塞爾）","game":"骰子","medium":"蝕刻版畫","size":"5.5×6.0公分","credit":"","p":["這是伊拉斯謨《愚人頌》書中的一幅小插圖。最初是霍爾拜因兄弟1516年在學者米科尼烏斯所藏書的頁邊畫的素描，梅里安把它刻成版畫，用於1676年在巴塞爾出版的版本。","戴著帶鈴鐺小丑帽的男人和戴兜帽的男人隔著圓桌擲骰子，桌上有三顆骰子。光著的腳讓人想起沉迷賭博的愚人。"],"spots":[["骰子","桌上的三顆骰子。"],["戴小丑帽的人","左邊探身的弄臣。"],["鈴鐺","小丑帽尖上的鈴鐺。"],["戴兜帽的人","右邊看著對手的人。"],["兜帽的鈴鐺","兜帽垂尾上的鈴鐺。"],["光腳","桌下光著的腳。"]]},"historiespel":{"title":"祖國歷史遊戲棋","artist":"約翰內斯·克里斯蒂安·本多普","date":"1816年","place":"荷蘭（阿姆斯特丹）","game":"擲骰競走棋（鵝棋型）","medium":"蝕刻與雕版","size":"50.3×61.0公分","credit":"","p":["這是一張走過荷蘭歷史的棋盤，由阿姆斯特丹的哈特曼出版。據美術館說，它和鵝棋一樣排著1到80的格子，1是「巴達維人起義」，80是「阿姆斯特丹航海學校」。","它改編自1787年的版本，第70到79格的事件被換掉，畫中最新的事件是1816年的。另有一張說明玩法的紙。格子裡排滿戰鬥場面和英雄肖像，應是邊玩邊學歷史的棋盤。"],"spots":[["起點1","左下的第1格。"],["終點80","中央的航海學校。"],["標題","「VADERLANDSCH HISTORIESPEL」。"],["肖像格","畫著人物肖像的格子。"],["70多號格","內圈的70多號格。"],["出版商","「HENDRIK GARTMAN」的名字。"]]},"daumier":{"title":"永遠不會被警察監視的巴黎人","artist":"奧諾雷·杜米埃","date":"1847年","place":"法國（巴黎）","game":"跳棋（國際跳棋）","medium":"石版畫","size":"29.7×22.6公分","credit":"","p":["這是諷刺畫家杜米埃的石版畫，刊登在巴黎《喧鬧報》1847年8月25日號上。上方有組畫標題「TOUT CE QU’ON VOUDRA（隨你所欲）」和第12號。","房間裡的小桌邊，兩位老人在下跳棋，中間的人托著腮看棋盤。下方的話是「永遠不會被高等警察監視的巴黎人」，應是在調侃這些安分下棋的老人。"],"spots":[["棋盤","桌上的跳棋盤。"],["走棋的人","左邊伸手拿棋子的人。"],["看棋的人","中間托腮的人。"],["右邊的人","盯著棋盤的人。"],["牆上的畫","後牆上的畫框。"],["題詞","「Parisiens qui ne seront jamais placés…」。"]]},"arnauts":{"title":"下跳棋的阿爾瑙特人","artist":"亨利·奧古斯丁·瓦朗坦（據讓-萊昂·熱羅姆原畫）","date":"1856—1886年","place":"法國（巴黎）","game":"跳棋（國際跳棋）","medium":"版畫（應為蝕刻）","size":"21.7×27.0公分","credit":"","p":["這是瓦朗坦根據法國畫家熱羅姆的畫刻製、由巴黎古皮爾公司出版的版畫，下方寫著「ARNAUTES JOUANT AUX DAMES（下跳棋的阿爾瑙特人）」。阿爾瑙特人是為鄂圖曼帝國效力的阿爾巴尼亞士兵。","據美術館說，兩個阿爾瑙特人在長凳上面對面下跳棋。左邊的人穿著多褶裙般的服裝，手裡擺弄著什麼；右邊的人叼著長菸管俯看棋盤。左邊牆上能看到熱羅姆的簽名。"],"spots":[["棋盤","兩人之間的跳棋盤。"],["左邊的人","穿多褶服裝坐著的人。"],["手","擺弄東西的手。"],["右邊的人","俯看棋盤的人。"],["菸管","右邊的人叼著的長菸管。"],["簽名","左牆上熱羅姆的簽名。"]]},"luyken":{"title":"抽菸下棋的土耳其人","artist":"揚·勒伊肯","date":"1698年","place":"荷蘭（阿姆斯特丹／台夫特出版）","game":"西洋棋","medium":"蝕刻與雕版","size":"30.5×19.1公分","credit":"","p":["這是勒伊肯為旅行家科內利斯·德布勒因的《小亞細亞遊記》（台夫特，1698年）第136頁刻的插圖。一塊版上有上下兩個場面，上為A，下為B。","上面的場面裡，六個戴頭巾的男人用長菸管抽菸，其中兩人在地毯上下西洋棋；下面是四個喝咖啡的女人和一個侍女。台座前沿整齊地擺著脫下的鞋。"],"spots":[["棋盤","地毯上的棋盤。"],["下棋的人","伸手拿棋子的人。"],["俯身的人","俯看棋盤的人。"],["菸管","用長菸管抽菸的人們。"],["脫下的鞋","前面擺成一排的鞋。"],["窗外的樹","窗外的樹木。"]]}};
